  "We're building our public track record on Google. If ARSSA has supported your business across the South Africa (SADC)–DRC corridor, we'd genuinely value a review — it helps other businesses make confident decisions.": {
    "en": "We're building our public track record on Google. If ARSSA has supported your business across the South Africa (SADC)–DRC corridor, we'd genuinely value a review — it helps other businesses make confident decisions.",
    "fr": "Nous construisons notre réputation publique sur Google. Si ARSSA a accompagné votre entreprise le long du corridor Afrique du Sud (SADC)–RDC, votre avis nous est précieux — il aide d'autres entreprises à prendre des décisions éclairées.",
    "sw": "Tunajenga rekodi yetu ya hadharani kwenye Google. Ikiwa ARSSA imesaidia biashara yako kwenye ukanda wa Afrika Kusini (SADC)–DRC, tungeshukuru sana kupata maoni yako — inasaidia biashara zingine kufanya maamuzi ya uhakika.",
    "ln": "Tozali kotonga lokumu na biso na Google. Soki ARSSA esungaki mombongo na yo na nzela ya Afrika ya Sudi (SADC)–RDC, tokozala na botondi mingi mpo na ndimbola na yo — esalisaka bakompanyi misusu kozwa mikano ya malamu.",
    "pt": "Estamos a construir o nosso registo público no Google. Se a ARSSA apoiou a sua empresa no corredor África do Sul (SADC)–RDC, valorizamos genuinamente a sua avaliação — ajuda outras empresas a tomar decisões com confiança.",
    "af": "Ons bou ons openbare rekord op Google. As ARSSA jou besigheid oor die Suid-Afrika (SADC)–DRK-korridor ondersteun het, sal ons werklik 'n resensie waardeer — dit help ander besighede om met selfvertroue besluite te neem.",
    "zu": "Sakha umlando wethu womphakathi ku-Google. Uma i-ARSSA isekele ibhizinisi lakho kulo lonke iphaseji laseNingizimu Afrika (SADC)–DRC, singakuthakasela kakhulu ukubuyekeza kwakho — kusiza amanye amabhizinisi enze izinqumo ezinokuzethemba.",
    "xh": "Sakha irekhodi yethu yoluntu ku-Google. Ukuba i-ARSSA iye yalixhasa ishishini lakho kuyo yonke indlela yoMzantsi Afrika (SADC)–DRC, singalixabisa ngokwenene uphononongo — linceda amanye amashishini enze izigqibo ngokuzithemba.",
    "zh": "我们正在 Google 上建立我们的公开记录。如果 ARSSA 曾为您的企业在南非 (SADC)–刚果（金）走廊提供支持，我们将非常感谢您的评价——这有助于其他企业做出自信的决策。",
    "ar": "نحن نبني سجلنا العام على Google. إذا كانت ARSSA قد دعمت عملك عبر ممر جنوب إفريقيا (SADC) – جمهورية الكونغو الديمقراطية، فإننا نقدّر بصدق تقييمك — فهو يساعد الشركات الأخرى في اتخاذ قرارات واثقة.",
    "es": "Estamos construyendo nuestro historial público en Google. Si ARSSA ha respaldado a su empresa a lo largo del corredor Sudáfrica (SADC)–RDC, valoraríamos enormemente su reseña: ayuda a otras empresas a tomar decisiones seguras.",
    "de": "Wir bauen unsere öffentliche Erfolgsbilanz auf Google auf. Wenn ARSSA Ihr Unternehmen entlang des Korridors Südafrika (SADC)–DR Kongo unterstützt hat, schätzen wir Ihre Bewertung sehr – sie hilft anderen Unternehmen, sichere Entscheidungen zu treffen.",
    "hi": "हम Google पर अपना सार्वजनिक ट्रैक रिकॉर्ड बना रहे हैं। यदि ARSSA ने दक्षिण अफ्रीका (SADC)–DRC कॉरिडोर में आपके व्यवसाय का समर्थन किया है, तो हम आपकी समीक्षा का वास्तविक मूल्यांकन करेंगे — यह अन्य व्यवसायों को आत्मविश्वास से निर्णय लेने में मदद करता है।",
    "ru": "Мы формируем нашу публичную репутацию в Google. Если ARSSA оказала поддержку вашему бизнесу в коридоре ЮАР (SADC) – ДР Конго, мы будем искренне признательны за отзыв — он помогает другим компаниям принимать уверенные решения.",
    "ja": "Google での公開実績を構築しています。ARSSA が南アフリカ (SADC) – コンゴ民主共和国回廊でお客様のビジネスを支援したことがある場合、レビューをいただければ幸いです。他の企業が自信を持って決断を下す助けになります。",
    "ko": "우리는 Google에서 공개적인 실적을 쌓아가고 있습니다. ARSSA가 남아프리카 (SADC)–DRC 회랑에서 귀하의 비즈니스를 지원했다면 리뷰를 남겨주시면 감사하겠습니다 — 다른 기업들이 자신감 있는 결정을 내리는 데 큰 도움이 됩니다.",
    "it": "Stiamo costruendo il nostro storico pubblico su Google. Se ARSSA ha supportato la tua azienda lungo il corridoio Sudafrica (SADC)–RDC, apprezzeremmo molto una recensione — aiuta altre imprese a prendere decisioni con fiducia.",
    "nl": "We bouwen aan ons openbare trackrecord op Google. Als ARSSA uw bedrijf heeft ondersteund over de corridor Zuid-Afrika (SADC)–DRC, waarderen we een beoordeling zeer — het helpt andere bedrijven zelfverzekerde beslissingen te nemen."
  },
