  "Agence Rebi Service South Africa — the South African (SADC) extension of ARS S.A.R.L. in the DRC, built to simplify and strengthen cross-border business.": {
    "en": "Agence Rebi Service South Africa — the South African (SADC) extension of ARS S.A.R.L. in the DRC, built to simplify and strengthen cross-border business.",
    "fr": "Agence Rebi Service South Africa — l'extension sud-africaine (SADC) d'ARS S.A.R.L. en RDC, créée pour simplifier et consolider le commerce transfrontalier.",
    "sw": "Agence Rebi Service South Africa — tawi la Afrika Kusini (SADC) la ARS S.A.R.L. nchini DRC, lililoundwa kurahisisha na kuimarisha biashara ya mipakani.",
    "ln": "Agence Rebi Service South Africa — etape ya Afrika ya Sudi (SADC) ya ARS S.A.R.L. na RDC, esalemi mpo na kopepisa mpe kolendisa mombongo ya katikati ya mikili.",
    "pt": "Agence Rebi Service South Africa — a extensão sul-africana (SADC) da ARS S.A.R.L. na RDC, criada para simplificar e fortalecer os negócios transfronteiriços.",
    "af": "Agence Rebi Service South Africa — die Suid-Afrikaanse (SADC) verlenging van ARS S.A.R.L. in die DRK, gebou om oorgrenshandel te vereenvoudig en te versterk.",
    "zu": "I-Agence Rebi Service South Africa — isandiso saseNingizimu Afrika (SADC) se-ARS S.A.R.L. e-DRC, eyakhelwe ukwenza lula nokuhlomisa ibhizinisi elinqamula imingcele.",
    "xh": "I-Agence Rebi Service South Africa — ulwandiso lwaseMzantsi Afrika (SADC) lwe-ARS S.A.R.L. e-DRC, eyakhelwe ukwenza lula nokomeleza ushishino olunqumla imida.",
    "zh": "Agence Rebi Service South Africa——ARS S.A.R.L. 在刚果（金）的南非 (SADC) 分支机构，旨在简化并加强跨境商业运作。",
    "ar": "Agence Rebi Service South Africa — الامتداد الجنوب إفريقي (SADC) لشركة ARS S.A.R.L. في جمهورية الكونغو الديمقراطية، تأسست لتبسيط وتعزيز التجارة عبر الحدود.",
    "es": "Agence Rebi Service South Africa: la extensión sudafricana (SADC) de ARS S.A.R.L. en la RDC, creada para simplificar y fortalecer el comercio transfronterizo.",
    "de": "Agence Rebi Service South Africa – der südafrikanische (SADC) Zweig der ARS S.A.R.L. in der DR Kongo, gegründet zur Vereinfachung und Stärkung des grenzüberschreitenden Handels.",
    "hi": "Agence Rebi Service South Africa — DRC में ARS S.A.R.L. का दक्षिण अफ्रीकी (SADC) विस्तार, सीमा पार व्यापार को सरल और मजबूत बनाने के लिए निर्मित।",
    "ru": "Agence Rebi Service South Africa — южноафриканское подразделение (SADC) компании ARS S.A.R.L. в ДР Конго, созданное для упрощения и укрепления трансграничного бизнеса.",
    "ja": "Agence Rebi Service South Africa — コンゴ民主共和国における ARS S.A.R.L. の南アフリカ (SADC) 拠点であり、国境を越えたビジネスを簡素化・強化するために設立されました。",
    "ko": "Agence Rebi Service South Africa — DRC 내 ARS S.A.R.L.의 남아프리카 (SADC) 확장 법인으로, 국경 간 비즈니스를 간소화하고 강화하기 위해 설립되었습니다.",
    "it": "Agence Rebi Service South Africa — l'estensione sudafricana (SADC) di ARS S.A.R.L. nella RDC, creata per semplificare e rafforzare il commercio transfrontaliero.",
    "nl": "Agence Rebi Service South Africa — de Zuid-Afrikaanse (SADC) uitbreiding van ARS S.A.R.L. in de DRC, opgericht om grensoverschrijdend zakendoen te vereenvoudigen en te versterken."
  },
