  "To be the leading partner that simplifies and strengthens cross-border business between South Africa (SADC) and the DRC, empowering pharmaceutical, cosmetic, and agri-food companies to expand with confidence.": {
    "en": "To be the leading partner that simplifies and strengthens cross-border business between South Africa (SADC) and the DRC, empowering pharmaceutical, cosmetic, and agri-food companies to expand with confidence.",
    "fr": "Être le partenaire de référence qui simplifie et renforce les affaires transfrontalières entre l'Afrique du Sud (SADC) et la RDC, en permettant aux entreprises pharmaceutiques, cosmétiques et agroalimentaires de se développer en toute confiance.",
    "sw": "Kuwa mshirika kiongozi anayerahisisha na kuimarisha biashara ya mipakani kati ya Afrika Kusini (SADC) na DRC, akiwezesha makampuni ya dawa, vipodozi, na vyakula vya kilimo kupanuka kwa ujasiri.",
    "ln": "Kozala moninga ya liboso oyo apekisaka mikakatano mpe alendisaka mombongo ya katikati ya Afrika ya Sudi (SADC) na RDC, mpo na kopesa makasi na bakompanyi ya nkisi, biloko ya bopeto, mpe biloko ya kolia mpo bakola na molende.",
    "pt": "Ser o parceiro líder que simplifica e fortalece os negócios transfronteiriços entre a África do Sul (SADC) e a RDC, capacitando empresas farmacêuticas, cosméticas e agroalimentares a expandir com confiança.",
    "af": "Om die toonaangewende vennoot te wees wat oorgrenshandel tussen Suid-Afrika (SADC) en die DRK vereenvoudig en versterk, en farmaseutiese, kosmetiese en landbouvoedsel-ondernemings bemagtig om met selfvertroue uit te brei.",
    "zu": "Ukuba ngumlingani ohamba phambili owenza lula futhi uqinise ibhizinisi elinqamula imingcele phakathi kweNingizimu Afrika (SADC) ne-DRC, enika amandla izinkampani zemithi, izimonyo, kanye nokudla kwezolimo ukuthi zande ngokuzethemba.",
    "xh": "Ukuba liqabane eliphambili elenza lula nelomeleza ushishino olunqumla imida phakathi koMzantsi Afrika (SADC) ne-DRC, lixhobisa iinkampani zamayeza, ezobuhle, nezokutya kwezolimo ukuba zande ngokuzithemba.",
    "zh": "成为简化并强化南非 (SADC) 与刚果（金）跨境商业的领先伙伴，赋能制药、美妆及农产品企业充满信心地拓展市场。",
    "ar": "أن نكون الشريك الرائد الذي يسهل ويعزز الأعمال عبر الحدود بين جنوب إفريقيا (SADC) وجمهورية الكونغو الديمقراطية، وتمكين شركات الأدوية ومستحضرات التجميل والصناعات الغذائية من التوسع بثقة.",
    "es": "Ser el socio líder que simplifique y fortalezca los negocios transfronterizos entre Sudáfrica (SADC) y la RDC, capacitando a las empresas farmacéuticas, cosméticas y agroalimentarias para expandirse con total confianza.",
    "de": "Der führende Partner zu sein, der den grenzüberschreitenden Handel zwischen Südafrika (SADC) und der DR Kongo vereinfacht und stärkt, damit Pharma-, Kosmetik- und Agrarunternehmen vertrauensvoll expandieren können.",
    "hi": "दक्षिण अफ्रीका (SADC) और DRC के बीच सीमा पार व्यापार को सरल और मजबूत बनाने वाला अग्रणी भागीदार बनना, फार्मास्युटिकल, कॉस्मेटिक और कृषि-खाद्य कंपनियों को आत्मविश्वास के साथ विस्तार करने के लिए सशक्त बनाना।",
    "ru": "Быть ведущим партнером, упрощающим и укрепляющим трансграничный бизнес между ЮАР (SADC) и ДР Конго, помогая фармацевтическим, косметическим и агропродовольственным компаниям уверенно масштабироваться.",
    "ja": "南アフリカ (SADC) とコンゴ民主共和国の国境を越えたビジネスを簡素化・強化し、製薬、化粧品、農産食品分野の企業が自信を持って事業を拡大できるよう支援する業界トップのパートナーを目指します。",
    "ko": "남아프리카 (SADC)와 DRC 간의 국경 간 비즈니스를 간소화하고 강화하여 제약, 화장품 및 농식품 기업들이 확신을 갖고 사업을 확장할 수 있도록 돕는 선도적인 파트너가 되는 것입니다.",
    "it": "Essere il partner leader che semplifica e rafforza il commercio transfrontaliero tra Sudafrica (SADC) e RDC, consentendo alle aziende farmaceutiche, cosmetiche e agroalimentari di espandersi con sicurezza.",
    "nl": "De toonaangevende partner zijn die grensoverschrijdend zakendoen tussen Zuid-Afrika (SADC) en de DRC vereenvoudigt en versterkt, en farmaceutische, cosmetische en agrofoodbedrijven in staat stelt met vertrouwen uit te breiden."
  },
