  "To provide structured, ethical, practical, and results-driven solutions helping SA companies establish, operate, and grow in the DRC through compliant facilitation, strategic market development, and integrated trade support.": {
    "en": "To provide structured, ethical, practical, and results-driven solutions helping SA companies establish, operate, and grow in the DRC through compliant facilitation, strategic market development, and integrated trade support.",
    "fr": "Fournir des solutions structurées, éthiques, pratiques et axées sur les résultats pour aider les entreprises sud-africaines à s'implanter, opérer et prospérer en RDC grâce à une facilitation conforme, un développement de marché stratégique et un support commercial intégré.",
    "sw": "Kutoa suluhu zilizopangwa, za kimaadili, za vitendo, na zinazoendeshwa na matokeo kusaidia makampuni ya Afrika Kusini kuanzisha, kufanya kazi, na kukua nchini DRC kupitia uwezeshaji unaozingatia sheria, maendeleo ya kimkakati ya soko, na usaidizi thabiti wa kibiashara.",
    "ln": "Kopesa masalisi ya mayele, ya bosembo, ya solo mpe oyo ezali komema matomba mpo na kosalisa bakompanyi ya Afrika ya Sudi kokota, kosala mpe kokola na RDC na nzela ya botosi mibeko, bopanzi zando na mayele, mpe lisungi mobimba ya mombongo.",
    "pt": "Fornecer soluções estruturadas, éticas, práticas e orientadas para resultados, ajudando as empresas sul-africanas a estabelecer-se, operar e crescer na RDC através de facilitação em conformidade, desenvolvimento estratégico de mercado e suporte comercial integrado.",
    "af": "Om gestruktureerde, etiese, praktiese en resultaatgedrewe oplossings te bied wat SA-maatskappye help om in die DRK te vestig, te bedryf en te groei deur voldoenende fasilitering, strategiese markontwikkeling en geïntegreerde handelsondersteuning.",
    "zu": "Ukuhlinzeka ngezixazululo ezihlelekile, ezinesimilo, ezingokoqobo, neziqhutshwa imiphumela ezisiza izinkampani zaseNingizimu Afrika ukuthi zisungule, zisebenze, futhi zikhule e-DRC ngokusebenzisa ukwenza lula okuhambisana nomthetho, ukuthuthukiswa kwemakethe yamasu, nokusekelwa kwezohwebo okuhlanganisiwe.",
    "xh": "Ukubonelela ngezisombululo ezicwangcisiweyo, zokuziphatha, ezisebenzayo, nezijolise kwiziphumo ezinceda iinkampani zaseMzantsi Afrika ukuba zizinzise, zisebenze, kwaye zikhule e-DRC ngokusebenzisa uququzelelo oluthobela imithetho, uphuhliso lwemarike yobuchule, kunye nenkxaso yorhwebo edityanisiweyo.",
    "zh": "通过合规便利化、战略性市场开发及综合贸易支持，提供结构化、合乎商业道德、务实且以成果为导向的解决方案，助力南非企业在刚果（金）成功设立、平稳运营并实现长远增长。",
    "ar": "تقديم حلول منظمة وأخلاقية وعملية وموجهة نحو تحقيق النتائج لمساعدة الشركات الجنوب إفريقية على التأسيس والعمل والنمو في جمهورية الكونغو الديمقراطية من خلال التسهيل المتوافق وتطوير السوق الاستراتيجي والدعم التجاري المتكامل.",
    "es": "Proporcionar soluciones estructuradas, éticas, prácticas y orientadas a resultados que ayuden a las empresas sudafricanas a establecerse, operar y crecer en la RDC mediante una facilitación conforme, desarrollo estratégico de mercado y soporte comercial integrado.",
    "de": "Strukturierte, ethische, praktische und ergebnisorientierte Lösungen bereitzustellen, die SA-Unternehmen beim Aufbau, Betrieb und Wachstum in der DR Kongo durch regelkonforme Abwicklung, strategische Marktentwicklung und integrierte Handelsunterstützung helfen.",
    "hi": "संरचित, नैतिक, व्यावहारिक और परिणाम-संचालित समाधान प्रदान करना जो आज्ञाकारी सुविधा, रणनीतिक बाजार विकास और एकीकृत व्यापार समर्थन के माध्यम से दक्षिण अफ्रीकी कंपनियों को DRC में स्थापित करने, संचालित करने और विकसित करने में मदद करते हैं।",
    "ru": "Предоставлять структурированные, этичные, практичные и ориентированные на результат решения, помогающие южноафриканским компаниям выходить, работать и развиваться в ДР Конго благодаря строгому комплаенсу, стратегическому развитию рынка и комплексной поддержке торговли.",
    "ja": "法令順守に基づく事業円滑化、戦略的市場開拓、統合的貿易支援を通じ、構造化され、倫理的で、実用的かつ成果重視のソリューションを提供し、南アフリカ企業がコンゴ民主共和国で確立、運営、成長できるよう尽力します。",
    "ko": "규정 준수 촉진, 전략적 시장 개발 및 통합 무역 지원을 통해 남아프리카 기업들이 DRC에서 성공적으로 정착하고 운영하며 성장할 수 있도록 체계적이고 윤리적이며 실용적이고 성과 중심적인 솔루션을 제공합니다.",
    "it": "Fornire soluzioni strutturate, etiche, pratiche e orientate ai risultati che aiutino le aziende sudafricane a stabilirsi, operare e crescere nella RDC attraverso una facilitazione conforme, uno sviluppo strategico del mercato e un supporto commerciale integrato.",
    "nl": "Het bieden van gestructureerde, ethische, praktische en resultaatgerichte oplossingen die Zuid-Afrikaanse bedrijven helpen zich te vestigen, te opereren en te groeien in de DRC door middel van conforme facilitering, strategische marktontwikkeling en geïntegreerde handelsondersteuning."
  },
