  "These values govern our operations, client relationships, and cross-border integrity.": {
    "en": "These values govern our operations, client relationships, and cross-border integrity.",
    "fr": "Ces valeurs guident nos opérations, nos relations clients et notre intégrité transfrontalière.",
    "sw": "Maadili haya yanaongoza shughuli zetu, mahusiano ya wateja, na uaminifu wetu wa mipakani.",
    "ln": "Mabongisi oyo etambwisaka misala na biso, boyokani na bakiliya, mpe bosembo ya mombongo ya mikili.",
    "pt": "Estes valores regem as nossas operações, as relações com os clientes e a nossa integridade transfronteiriça.",
    "af": "Hierdie waardes rig ons bedrywighede, kliënteverhoudings en oorgrens-integriteit.",
    "zu": "Lezi zimiso zilawula imisebenzi yethu, ubudlelwano namakhasimende, kanye nobuqotho bethu obunqamula imingcele.",
    "xh": "Ezi nqobo zilawula imisebenzi yethu, ubudlelwane nabathengi, kunye nokuthembeka kwethu okunqumla imida.",
    "zh": "这些价值观指导着我们的日常运营、客户伙伴关系以及跨境商业信誉。",
    "ar": "تحكم هذه القيم جميع عملياتنا وعلاقاتنا مع العملاء ونزاهتنا عبر الحدود.",
    "es": "Estos valores rigen nuestras operaciones, relaciones con clientes e integridad transfronteriza.",
    "de": "Diese Werte leiten unser operatives Handeln, unsere Kundenbeziehungen und unsere Integrität im Außenhandel.",
    "hi": "ये मूल्य हमारे संचालन, ग्राहक संबंधों और सीमा पार अखंडता को नियंत्रित करते हैं।",
    "ru": "Эти ценности определяют наши операционные процессы, отношения с клиентами и трансграничную честность.",
    "ja": "これらの価値観は、日々の実務、顧客との信頼関係、そして国境を越えた誠実さを律しています。",
    "ko": "이 가치들은 우리의 일상 운영, 고객 관계 및 국경 간 신뢰성을 지탱하는 근간입니다.",
    "it": "Questi valori guidano le nostre operazioni, le relazioni con i clienti e l'integrità transfrontaliera.",
    "nl": "Deze waarden sturen onze activiteiten, klantrelaties en grensoverschrijdende integriteit."
  },
