  "Ethical, compliant and transparent cross-border practices in everything we execute.": {
    "en": "Ethical, compliant and transparent cross-border practices in everything we execute.",
    "fr": "Des pratiques transfrontalières éthiques, conformes et transparentes dans tout ce que nous entreprenons.",
    "sw": "Mienendo ya kimaadili, inayozingatia sheria na ya uwazi katika kila kitu tunachotekeleza.",
    "ln": "Misala ya bosembo, ya kotosa mibeko mpe ya polele na makambo nionso oyo tosalaka.",
    "pt": "Práticas transfronteiriças éticas, em conformidade e transparentes em tudo o que executamos.",
    "af": "Etiese, voldoenende en deursigtige oorgrenspraktyke in alles wat ons uitvoer.",
    "zu": "Izenzo zokuziphatha, ezithobelayo nezingafihli lutho kunoma yini esiyenzayo.",
    "xh": "Iindlela zokuziphatha ngokusesikweni, ezithobela umthetho nezingafihliyo kuyo yonke into esiyenzayo.",
    "zh": "在我们所执行的每一项工作中，坚持合乎商业伦理、严格合规且高度透明。",
    "ar": "ممارسات تجارية عبر الحدود تتسم بالأخلاقية والامتثال والشفافية في كل ما نقوم به.",
    "es": "Prácticas transfronterizas éticas, conformes y transparentes en todo lo que ejecutamos.",
    "de": "Ethische, gesetzeskonforme und transparente Handelspraktiken bei allem, was wir tun.",
    "hi": "हमारे द्वारा निष्पादित प्रत्येक कार्य में नैतिक, अनुपालन और पारदर्शी सीमा पार प्रथाएं।",
    "ru": "Этичные, соответствующие закону и прозрачные методы трансграничной работы во всем, что мы реализуем.",
    "ja": "私たちが実行するすべての業務において、倫理的で、法令に準拠し、透明性の高い国境間実務を徹底します。",
    "ko": "우리가 실행하는 모든 업무에서 윤리적이고 규정을 준수하며 투명한 국경 간 비즈니스 관행을 지킵니다.",
    "it": "Pratiche transfrontaliere etiche, conformi e trasparenti in tutto ciò che realizziamo.",
    "nl": "Ethische, conforme en transparante grensoverschrijdende praktijken in alles wat we uitvoeren."
  },
