  "Clear processes, upfront cost structures and systematic documentation across all mandates.": {
    "en": "Clear processes, upfront cost structures and systematic documentation across all mandates.",
    "fr": "Des processus limpides, des structures de coûts transparentes et une documentation systématique pour chaque mandat.",
    "sw": "Michakato iliyo wazi, miundo ya gharama ya mapema na nyaraka za kimfumo katika majukumu yote.",
    "ln": "Banzela ya polele, motuya ya mbongo eyebani na ebandeli mpe mikanda ya sikisiki mpo na misala nionso.",
    "pt": "Processos claros, estruturas de custos transparentes e documentação sistemática em todos os mandatos.",
    "af": "Duidelike prosesse, vooraf kostestrukture en sistematiese dokumentasie oor alle mandate heen.",
    "zu": "Izinqubo ezicacile, izinhlaka zezindleko zangaphambili kanye nemibhalo ehlelekile kuyo yonke imisebenzi.",
    "xh": "Iinkqubo ezicacileyo, izakhiwo zeendleko eziphambi kwexesha kunye namaxwebhu acwangcisiweyo kuyo yonke imisebenzi.",
    "zh": "在所有受托事项中保持流程清晰、费用结构事前透明并实现系统化文档归档。",
    "ar": "إجراءات واضحة وهياكل تكلفة معلنة مسبقاً وتوثيق منهجي ودقيق عبر جميع المهام.",
    "es": "Procesos claros, estructuras de costos transparentes y documentación sistemática en todos los mandatos.",
    "de": "Klare Prozesse, transparente Kostenstrukturen und systematische Dokumentation bei allen Aufträgen.",
    "hi": "सभी अधिदेशों में स्पष्ट प्रक्रियाएं, अग्रिम लागत संरचनाएं और व्यवस्थित दस्तावेज़ीकरण।",
    "ru": "Четкие процессы, прозрачные структуры расходов и систематическое документирование по всем проектам.",
    "ja": "すべての受託業務において、明確なプロセス、事前の明瞭な費用体系、体系的な文書管理を徹底します。",
    "ko": "모든 프로젝트에 걸쳐 명확한 프로세스, 사전 공개된 투명한 비용 구조 및 체계적인 문서화를 실천합니다.",
    "it": "Processi chiari, strutture di costo trasparenti e documentazione sistematica in ogni incarico.",
    "nl": "Duidelijke processen, transparante kostenstructuren en systematische documentatie bij alle opdrachten."
  },
