  "Whether you are assessing market entry or expanding existing operations in the DRC, ARSSA provides the structure and execution you need.": {
    "en": "Whether you are assessing market entry or expanding existing operations in the DRC, ARSSA provides the structure and execution you need.",
    "fr": "Que vous évaluiez votre entrée sur le marché ou développiez des activités existantes en RDC, ARSSA vous apporte la structure et l'exécution dont vous avez besoin.",
    "sw": "Iwe unatathmini kuingia sokoni au kupanua shughuli zilizopo nchini DRC, ARSSA inakupa muundo na utekelezaji unaohitaji.",
    "ln": "Ata soki ozali kotala ndenge ya kokota na zando to kokolisa misala oyo ozali na yango na RDC, ARSSA epesaka yo ebongiseli mpe bosaleli oyo osengeli na yango.",
    "pt": "Quer esteja a avaliar a entrada no mercado ou a expandir operações existentes na RDC, a ARSSA fornece a estrutura e a execução de que necessita.",
    "af": "Of jy nou marktoetrede beoordeel of bestaande bedrywighede in die DRK uitbrei, ARSSA bied die struktuur en uitvoering wat jy nodig het.",
    "zu": "Kungakhathaliseki ukuthi uhlola ukungena emakethe noma ukwandisa imisebenzi ekhona e-DRC, i-ARSSA inikeza isakhiwo nokusetshenziswa okudingayo.",
    "xh": "Nokuba uhlola ukungena kwimarike okanye wandisa imisebenzi ekhoyo e-DRC, i-ARSSA ibonelela ngolwakhiwo kunye nokwenziwa komsebenzi okufunayo.",
    "zh": "无论您是在评估市场准入可行性，还是在刚果（金）拓展既有业务，ARSSA 都能提供您所需的完备架构与实地执行力。",
    "ar": "سواء كنت تقيّم دخول السوق أو توسع عملياتك الحالية في جمهورية الكونغو الديمقراطية، توفر لك ARSSA الهيكل والتنفيذ الذي تحتاجه.",
    "es": "Ya sea que esté evaluando la entrada al mercado o expandiendo operaciones existentes en la RDC, ARSSA proporciona la estructura y ejecución que necesita.",
    "de": "Egal, ob Sie den Markteintritt prüfen oder bestehende Aktivitäten in der DR Kongo ausbauen – ARSSA bietet Ihnen die nötige Struktur und Umsetzung.",
    "hi": "चाहे आप बाजार में प्रवेश का आकलन कर रहे हों या DRC में मौजूदा संचालन का विस्तार कर रहे हों, ARSSA आपको वह संरचना और निष्पादन प्रदान करता है जिसकी आपको आवश्यकता है।",
    "ru": "Оцениваете ли вы выход на рынок или расширяете текущие операции в ДР Конго, ARSSA предоставит структуру и исполнение, необходимые для успеха.",
    "ja": "市場参入の検討段階でも、コンゴ民主共和国での既存事業の拡大でも、ARSSA が必要な体制と実行力を提供します。",
    "ko": "시장 진입을 검토 중이거나 DRC 내 기존 사업을 확장하려는 경우 모두, ARSSA가 필요한 체계와 실행력을 제공합니다.",
    "it": "Sia che tu stia valutando l'ingresso nel mercato o espandendo le operazioni esistenti nella RDC, ARSSA fornisce la struttura e l'esecuzione di cui hai bisogno.",
    "nl": "Of u nu markttoetreding onderzoekt of bestaande activiteiten in de DRC uitbreidt, ARSSA biedt de structuur en uitvoering die u nodig heeft."
  },
