  "One integrated partner instead of a chain of disconnected service providers — built specifically for the South Africa (SADC)–DRC corridor.": {
    "en": "One integrated partner instead of a chain of disconnected service providers — built specifically for the South Africa (SADC)–DRC corridor.",
    "fr": "Un partenaire intégré unique plutôt qu'une chaîne de prestataires déconnectés — conçu spécialement pour le corridor Afrique du Sud (SADC)–RDC.",
    "sw": "Mshirika mmoja aliyeunganishwa badala ya msururu wa watoa huduma wasiounganishwa — aliyejengwa mahususi kwa ukanda wa Afrika Kusini (SADC)–DRC.",
    "ln": "Moninga moko oyo asangisi makambo nionso na esika ya bato ebele ya kokesana — oyo asalemi mpenza mpo na nzela ya Afrika ya Sudi (SADC)–RDC.",
    "pt": "Um parceiro integrado em vez de uma cadeia de prestadores de serviços desconectados — construído especificamente para o corredor África do Sul (SADC)–RDC.",
    "af": "'n Geïntegreerde vennoot in plaas van 'n ketting van ontkoppelde diensverskaffers — spesifiek gebou vir die Suid-Afrika (SADC)–DRK-korridor.",
    "zu": "Umlingani oyedwa ohlanganisiwe esikhundleni sochungechunge lwabahlinzeki bezinsizakalo abanganamathele — owakhelwe ngokukhethekile iphaseji laseNingizimu Afrika (SADC)–DRC.",
    "xh": "Iqabane elinye elidityanisiweyo endaweni yothotho lwababoneleli beenkonzo abangaqhagamshelwanga — elakhelwe ngokukodwa indlela yoMzantsi Afrika (SADC)–DRC.",
    "zh": "一个综合合作伙伴取代互不相属的多家中介机构——专为南非 (SADC)–刚果（金）走廊量身打造。",
    "ar": "شريك متكامل واحد بدلاً من سلسلة من مقدمي الخدمات المنفصلين — مصمم خصيصاً لممر جنوب إفريقيا (SADC) – جمهورية الكونغو الديمقراطية.",
    "es": "Un socio integrado en lugar de una cadena de proveedores inconexos, creado específicamente para el corredor Sudáfrica (SADC)–RDC.",
    "de": "Ein einziger integrierter Partner statt einer Kette unverbundener Dienstleister – speziell für den Korridor Südafrika (SADC)–DR Kongo geschaffen.",
    "hi": "अव्यवस्थित सेवा प्रदाताओं की श्रृंखला के बजाय एक एकीकृत भागीदार — विशेष रूप से दक्षिण अफ्रीका (SADC)–DRC कॉरिडोर के लिए निर्मित।",
    "ru": "Единый интегрированный партнер вместо цепочки разрозненных поставщиков услуг — создан специально для коридора ЮАР (SADC) – ДР Конго.",
    "ja": "分断された複数の業者ではなく、単一の統合パートナー — 南アフリカ (SADC) – コンゴ民主共和国回廊のために特別に構築されました。",
    "ko": "분리된 서비스 제공업체 네트워크 대신 단일 통합 파트너 — 남아프리카 (SADC)–DRC 회랑을 위해 특별히 설립되었습니다.",
    "it": "Un unico partner integrato anziché una catena di fornitori scollegati — creato specificamente per il corridoio Sudafrica (SADC)–RDC.",
    "nl": "Eén geïntegreerde partner in plaats van een keten van losstaande dienstverleners — specifiek gebouwd voor de corridor Zuid-Afrika (SADC)–DRC."
  },
