  "ARSSA is backed by the operational legacy of the ARS Group — years of complex, regulated and large-scale projects across the DRC.": {
    "en": "ARSSA is backed by the operational legacy of the ARS Group — years of complex, regulated and large-scale projects across the DRC.",
    "fr": "ARSSA s'appuie sur l'héritage opérationnel du Groupe ARS — des années de projets complexes, réglementés et d'envergure à travers la RDC.",
    "sw": "ARSSA inaungwa mkono na urithi wa kiutendaji wa Kikundi cha ARS — miaka ya miradi changamano, inayodhibitiwa na ya kiwango kikubwa kote DRC.",
    "ln": "ARSSA elendisami na libula ya misala ya ARS Group — mibu mingi ya misala ya minene, ya mibeko mpe ya mikakatano na RDC mobimba.",
    "pt": "A ARSSA é apoiada pelo legado operacional do Grupo ARS — anos de projetos complexos, regulamentados e de grande escala em toda a RDC.",
    "af": "ARSSA word gerugsteun deur die operasionele nalatenskap van die ARS Groep — jare van komplekse, gereguleerde en grootskaalse projekte oor die DRK.",
    "zu": "I-ARSSA isekelwa ifa lokusebenza le-ARS Group — iminyaka yamaphrojekthi ayinkimbinkimbi, alawulwayo namakhulu kulo lonke i-DRC.",
    "xh": "I-ARSSA ixhaswe lilifa lokusebenza le-ARS Group — iminyaka yeeprojekthi ezinzima, ezilawulwayo nezinkulu kuyo yonke i-DRC.",
    "zh": "ARSSA 依托 ARS 集团坚实的运营积淀——多年来在刚果（金）成功执行多项复杂、高监管及大型项目。",
    "ar": "تحظى ARSSA بدعم من الإرث التشغيلي العريق لمجموعة ARS — سنوات من المشاريع الكبرى والمعقدة والمنظمة في جمهورية الكونغو الديمقراطية.",
    "es": "ARSSA está respaldada por el legado operativo del Grupo ARS: años de proyectos complejos, regulados y a gran escala en toda la RDC.",
    "de": "ARSSA stützt sich auf die operative Erfolgsbilanz der ARS-Gruppe – jahrelange Erfahrung mit komplexen, regulierten Großprojekten in der DR Kongo.",
    "hi": "ARSSA को ARS ग्रुप की परिचालन विरासत का समर्थन प्राप्त है — पूरे DRC में वर्षों की जटिल, विनियमित और बड़े पैमाने की परियोजनाएं।",
    "ru": "ARSSA опирается на многолетний опыт группы ARS — годы реализации сложных, строго регулируемых и масштабных проектов по всей ДР Конго.",
    "ja": "ARSSA は ARS グループの事業実績に支えられています — コンゴ民主共和国全域における長年の複雑かつ規制の厳しい大規模プロジェクトの経験があります。",
    "ko": "ARSSA는 ARS 그룹의 운영 유산을 기반으로 합니다 — DRC 전역에서 수년간 수행된 복잡하고 규제된 대규모 프로젝트의 풍부한 실적을 보유하고 있습니다.",
    "it": "ARSSA è supportata dall'eredità operativa del Gruppo ARS — anni di progetti complessi, regolamentati e su larga scala in tutta la RDC.",
    "nl": "ARSSA wordt ondersteund door het operationele erfgoed van de ARS Groep — jaren van complexe, gereguleerde en grootschalige projecten in de DRC."
  },
