  "ARSSA is built for organisations that need more than reports — they need dependable, on-the-ground execution across the South Africa (SADC)–DRC corridor.": {
    "en": "ARSSA is built for organisations that need more than reports — they need dependable, on-the-ground execution across the South Africa (SADC)–DRC corridor.",
    "fr": "ARSSA s'adresse aux organisations qui recherchent bien plus que des rapports d'études — une exécution fiable et concrète sur le terrain le long du corridor Afrique du Sud (SADC)–RDC.",
    "sw": "ARSSA imeundwa kwa mashirika yanayohitaji zaidi ya ripoti — yanahitaji utekelezaji wa kuaminika ardhini katika ukanda wa Afrika Kusini (SADC)–DRC.",
    "ln": "ARSSA esalemi mpo na bakompanyi oyo esengeli na makambo koleka ba rapor — basengeli na bosaleli ya solosolo na mabele na nzela ya Afrika ya Sudi (SADC)–RDC.",
    "pt": "A ARSSA foi concebida para organizações que precisam de mais do que relatórios — necessitam de execução fiável no terreno em todo o corredor África do Sul (SADC)–RDC.",
    "af": "ARSSA is gebou vir organisasies wat meer as verslae benodig — hulle benodig betroubare uitvoering op die grond oor die Suid-Afrika (SADC)–DRK-korridor.",
    "zu": "I-ARSSA yakhelwe izinhlangano ezidinga okungaphezulu kwemibiko — zidinga ukusetshenziswa okuthembekile phansi kulo lonke iphaseji laseNingizimu Afrika (SADC)–DRC.",
    "xh": "I-ARSSA yenzelwe imibutho efuna okungaphezulu kuneengxelo — ifuna ukwenziwa komsebenzi okuthembekileyo endaweni kuyo yonke indlela yoMzantsi Afrika (SADC)–DRC.",
    "zh": "ARSSA 专为不仅仅需要书面报告、更渴求在南非 (SADC)–刚果（金）走廊获得可靠实地执行力的企业而打造。",
    "ar": "تم بناء ARSSA للمؤسسات التي تحتاج إلى أكثر من مجرد تقارير ورقية — إنها بحاجة إلى تنفيذ ميداني موثوق عبر ممر جنوب إفريقيا (SADC) – جمهورية الكونغو الديمقراطية.",
    "es": "ARSSA está creada para organizaciones que necesitan más que informes: requieren una ejecución confiable sobre el terreno a lo largo del corredor Sudáfrica (SADC)–RDC.",
    "de": "ARSSA ist für Organisationen konzipiert, die mehr als Berichte brauchen – sie benötigen verlässliche Umsetzung vor Ort im Korridor Südafrika (SADC)–DR Kongo.",
    "hi": "ARSSA उन संगठनों के लिए बनाया गया है जिन्हें रिपोर्ट से अधिक की आवश्यकता है — उन्हें दक्षिण अफ्रीका (SADC)–DRC कॉरिडोर में विश्वसनीय, जमीनी निष्पादन की आवश्यकता है।",
    "ru": "ARSSA создана для организаций, которым нужны не просто аналитические отчеты, а надежное исполнение на местах в коридоре ЮАР (SADC) – ДР Конго.",
    "ja": "ARSSA は、単なる報告書以上のもの、すなわち南アフリカ (SADC) – コンゴ民主共和国回廊における信頼できる現場での確実な実行力を求める組織のために構築されています。",
    "ko": "ARSSA는 단순한 보고서 이상의 것, 즉 남아프리카 (SADC)–DRC 회랑에서 신뢰할 수 있는 현장 실행력을 필요로 하는 조직을 위해 설립되었습니다.",
    "it": "ARSSA è concepita per le organizzazioni che cercano più di semplici relazioni: necessitano di un'esecuzione affidabile sul campo lungo il corridoio Sudafrica (SADC)–RDC.",
    "nl": "ARSSA is gebouwd voor organisaties die meer nodig hebben dan rapporten — ze hebben betrouwbare uitvoering ter plaatse nodig over de corridor Zuid-Afrika (SADC)–DRC."
  },
