  "Five specialised divisions operating in unison — covering everything from market entry and compliance to distribution and cross-border trade.": {
    "en": "Five specialised divisions operating in unison — covering everything from market entry and compliance to distribution and cross-border trade.",
    "fr": "Cinq divisions spécialisées agissant en parfaite synergie — couvrant l'entrée sur le marché, la conformité, la distribution et le commerce transfrontalier.",
    "sw": "Vitengo vitano maalumu vinavyofanya kazi kwa umoja — vikishughulikia kila kitu kuanzia kuingia sokoni na kufuata sheria hadi usambazaji na biashara ya mipakani.",
    "ln": "Biteni mitano ya mosala oyo esalaka elongo — kobanda na kokota na zando, kotosa mibeko, kopesa biloko mpe mombongo ya mikili.",
    "pt": "Cinco divisões especializadas a operar em uníssono — cobrindo desde a entrada no mercado e conformidade até à distribuição e comércio transfronteiriço.",
    "af": "Vyf gespesialiseerde afdelings wat in harmonie funksioneer — wat alles dek van marktoetrede en voldoening tot verspreiding en oorgrenshandel.",
    "zu": "Izigaba ezinhlanu ezikhethekile ezisebenza ngokubambisana — ezihlanganisa yonke into kusukela ekungeneni emakethe nokuthobela imithetho kuya ekusabalaliseni nasezihwebeni ezinqamula imingcele.",
    "xh": "Amacandelo amahlanu akhethekileyo asebenza ngamxhelo mnye — aquka yonke into ukusuka ekungeneni kwimarike nokuthotyelwa komthetho ukuya kusasazo norhwebo olunqumla imida.",
    "zh": "五大专业部门协同运作——涵盖从市场准入、法规合规到实地分销及跨境贸易的各个环节。",
    "ar": "خمسة أقسام متخصصة تعمل في انسجام تام — تغطي كل شيء بدءاً من دخول السوق والامتثال وحتى التوزيع والتجارة عبر الحدود.",
    "es": "Cinco divisiones especializadas que operan al unísono: cubren desde la entrada al mercado y el cumplimiento hasta la distribución y el comercio transfronterizo.",
    "de": "Fünf spezialisierte Abteilungen im perfekten Zusammenspiel – vom Markteintritt und der Compliance bis zu Vertrieb und Außenhandel.",
    "hi": "एक साथ काम करने वाले पांच विशेष प्रभाग — बाजार में प्रवेश और अनुपालन से लेकर वितरण और सीमा पार व्यापार तक सब कुछ शामिल है।",
    "ru": "Пять специализированных подразделений, действующих слаженно — от выхода на рынок и комплаенса до дистрибуции и трансграничной торговли.",
    "ja": "市場参入、コンプライアンスから流通、国境を越えた貿易に至るまで、5つの専門部門が緊密に連携して対応します。",
    "ko": "시장 진출 및 규정 준수부터 유통 및 국경 간 무역에 이르기까지, 5개 전문 사업부가 하나로 유기적으로 운영됩니다.",
    "it": "Cinque divisioni specializzate che operano all'unisono — dall'ingresso nel mercato e conformità fino alla distribuzione e al commercio transfrontaliero.",
    "nl": "Vijf gespecialiseerde divisies die in harmonie opereren — van markttoetreding en naleving tot distributie en grensoverschrijdende handel."
  },
