  "See what each division delivers": {
    "en": "See what each division delivers",
    "fr": "Découvrez les prestations de chaque division",
    "sw": "Ona kile ambacho kila kitengo kinatoa",
    "ln": "Tala maye eteni mokomoko epesaka",
    "pt": "Veja o que cada divisão oferece",
    "af": "Kyk wat elke afdeling lewer",
    "zu": "Bona ukuthi isigaba ngasinye siletha ini",
    "xh": "Bona oko kuziswa licandelo ngalinye",
    "zh": "探索各大业务部门的核心交付成果",
    "ar": "تعرف على ما يقدمه كل قسم من أقسامنا",
    "es": "Vea lo que ofrece cada división",
    "de": "Erfahren Sie, was jede Abteilung leistet",
    "hi": "देखें कि प्रत्येक प्रभाग क्या प्रदान करता है",
    "ru": "Узнайте, что предоставляет каждое подразделение",
    "ja": "各部門の具体的な提供価値を確認する",
    "ko": "각 사업부별 제공 서비스를 확인해 보십시오",
    "it": "Scopri cosa offre ciascuna divisione",
    "nl": "Bekijk wat elke divisie levert"
  },
  "Tap a division below to see exactly how ARSSA handles that phase of your cross-border journey — from first market entry through to ongoing operations.": {
    "en": "Tap a division below to see exactly how ARSSA handles that phase of your cross-border journey — from first market entry through to ongoing operations.",
    "fr": "Sélectionnez une division ci-dessous pour découvrir précisément comment ARSSA pilote cette étape de votre développement transfrontalier — de la première implantation aux opérations pérennes.",
    "sw": "Bofya kitengo hapa chini ili kuona hasa jinsi ARSSA inavyoshughulikia hatua hiyo ya safari yako ya mipakani — kuanzia uingiaji wa kwanza sokoni hadi shughuli zinazoendelea.",
    "ln": "Pona eteni moko na nse mpo na kotala ndenge nini ARSSA etambwisaka eteni wana ya mombongo na yo — kobanda na kokota na zando tii na misala ya mikolo nionso.",
    "pt": "Selecione uma divisão abaixo para ver exatamente como a ARSSA gere essa fase da sua jornada transfronteiriça — desde a entrada inicial no mercado até às operações contínuas.",
    "af": "Tik op 'n afdeling hieronder om presies te sien hoe ARSSA daardie fase van jou oorgrensreis hanteer — van eerste marktoetrede tot deurlopende bedrywighede.",
    "zu": "Thepha isigaba ngezansi ukuze ubone kahle ukuthi i-ARSSA isisingatha kanjani leso sigaba sohambo lwakho olunqamula imingcele — kusukela ekungeneni kokuqala emakethe kuya emisebenzini eqhubekayo.",
    "xh": "Cofa icandelo ngezantsi ukuze ubone ncam indlela i-ARSSA esisingatha ngayo eso sigaba sohambo lwakho olunqumla imida — ukusuka ekungeneni kokuqala kwimarike ukuya kwimisebenzi eqhubekayo.",
    "zh": "点击下方业务部门，深入了解 ARSSA 如何为您全程护航跨境之旅——从初期市场准入到日常规模化运营。",
    "ar": "انقر على أحد الأقسام أدناه لتتعرف بدقة على كيفية إدارة ARSSA لتلك المرحلة من مسار أعمالك عبر الحدود — بدءاً من دخول السوق الأول وحتى العمليات اليومية المستمرة.",
    "es": "Toque una división a continuación para ver con exactitud cómo ARSSA gestiona esa fase de su trayectoria transfronteriza: desde la entrada inicial al mercado hasta las operaciones continuas.",
    "de": "Wählen Sie unten eine Abteilung aus, um genau zu sehen, wie ARSSA diese Phase Ihres Markteintritts steuert – vom ersten Marktschritt bis zum laufenden Betrieb.",
    "hi": "यह देखने के लिए नीचे दिए गए किसी प्रभाग पर टैप करें कि ARSSA आपकी सीमा पार यात्रा के उस चरण को कैसे संभालता है — प्रारंभिक बाजार प्रवेश से लेकर चल रहे संचालन तक।",
    "ru": "Выберите подразделение ниже, чтобы узнать, как ARSSA курирует этот этап трансграничного развития — от первоначального выхода на рынок до повседневных операций.",
    "ja": "部門を選択すると、市場参入の初期段階から日常業務に至るまで、ARSSA が越境事業の各フェーズをどのように統括するかご確認いただけます。",
    "ko": "아래에서 사업부를 선택하시면 최초 시장 진입부터 지속적인 운영에 이르기까지, ARSSA가 국경 간 비즈니스를 어떻게 전담하는지 확인하실 수 있습니다.",
    "it": "Seleziona una divisione qui sotto per scoprire esattamente come ARSSA gestisce ogni fase del tuo percorso transfrontaliero — dal primo ingresso sul mercato fino alle operazioni continuative.",
    "nl": "Tik hieronder op een divisie om precies te zien hoe ARSSA die fase van uw grensoverschrijdende traject beheert — van de eerste markttoetreding tot de lopende activiteiten."
  },
