  "Heavily regulated industries need a partner who understands compliance as well as commerce. That's where ARSSA operates.": {
    "en": "Heavily regulated industries need a partner who understands compliance as well as commerce. That's where ARSSA operates.",
    "fr": "Les secteurs hautement réglementés ont besoin d'un partenaire maîtrisant aussi bien la conformité que le commerce. C'est le cœur de métier d'ARSSA.",
    "sw": "Viwanda vinavyodhibitiwa sana vinahitaji mshirika anayeelewa kanuni na biashara pia. Hapo ndipo ARSSA inafanya kazi.",
    "ln": "Misala oyo elandeli mibeko makasi esengeli na moninga oyo ayebi mibeko mpe mombongo elongo. Wana nde mosala ya ARSSA.",
    "pt": "As indústrias altamente regulamentadas precisam de um parceiro que compreenda tanto a conformidade quanto o comércio. É aí que a ARSSA opera.",
    "af": "Swaar gereguleerde nywerhede benodig 'n vennoot wat voldoening sowel as handel verstaan. Dit is waar ARSSA opereer.",
    "zu": "Izimboni ezilawulwa kakhulu zidinga umlingani oqonda ukuthobela kanye nezohwebo. Yilapho i-ARSSA isebenza khona.",
    "xh": "Ii-industri ezilawulwa kakhulu zifuna iqabane eliqonda ukuthotyelwa komthetho kunye norhwebo. Kulapho i-ARSSA isebenza khona.",
    "zh": "强监管行业需要一个既懂法规红线又精通商业落地的坚实伙伴。这正是 ARSSA 的立足之本。",
    "ar": "تحتاج الصناعات الخاضعة لتنظيمات مشددة إلى شريك يستوعب معايير الامتثال ومتطلبات التجارة في آن واحد. وهذا هو صميم عمل ARSSA.",
    "es": "Las industrias altamente reguladas necesitan un socio que comprenda tanto el cumplimiento como el comercio. Ahí es donde opera ARSSA.",
    "de": "Stark regulierte Industrien brauchen einen Partner, der Compliance ebenso beherrscht wie das operative Geschäft. Genau hier ist ARSSA zu Hause.",
    "hi": "भारी रूप से विनियमित उद्योगों को एक ऐसे भागीदार की आवश्यकता होती है जो अनुपालन के साथ-साथ वाणिज्य को भी समझता हो। यहीं पर ARSSA काम करता है।",
    "ru": "Строго регулируемые отрасли нуждаются в партнере, разбирающемся в комплаенсе так же глубоко, как и в коммерции. Именно в этой сфере работает ARSSA.",
    "ja": "規制の厳しい産業分野では、コンプライアンスと商業実務の双方を熟知したパートナーが不可欠です。それこそが ARSSA の強みです。",
    "ko": "엄격하게 규제되는 산업은 법적 규제와 비즈니스 실무를 모두 완벽히 이해하는 파트너를 필요로 합니다. 그것이 바로 ARSSA의 전문 영역입니다.",
    "it": "I settori fortemente regolamentati necessitano di un partner che comprenda sia la conformità sia il commercio. È esattamente qui che opera ARSSA.",
    "nl": "Zwaar gereguleerde sectoren hebben een partner nodig die zowel naleving als commercie begrijpt. Dat is waar ARSSA opereert."
  },
