  "Whether you're exploring the market for the first time or ready to scale distribution, ARSSA gives you one accountable partner for the whole journey — compliant, coordinated, and built for the South Africa (SADC)–DRC corridor.": {
    "en": "Whether you're exploring the market for the first time or ready to scale distribution, ARSSA gives you one accountable partner for the whole journey — compliant, coordinated, and built for the South Africa (SADC)–DRC corridor.",
    "fr": "Que vous découvriez ce marché pour la première fois ou que vous soyez prêt à intensifier votre distribution, ARSSA vous garantit un partenaire responsable tout au long du parcours — conforme, coordonné et spécialement conçu pour le corridor Afrique du Sud (SADC)–RDC.",
    "sw": "Iwe unachunguza soko kwa mara ya kwanza au uko tayari kuongeza usambazaji, ARSSA inakupa mshirika mmoja anayewajibika kwa safari nzima — anayezingatia sheria, aliyeratibiwa, na aliyejengwa kwa ajili ya ukanda wa Afrika Kusini (SADC)–DRC.",
    "ln": "Ata soki ozali kotala zando mpo na mbala ya yambo to ozali ya kokolisa bopesi biloko, ARSSA epesaka yo moninga moko ya mokumba na mobembo mobimba — oyo atosi mibeko, oyo abongisami malamu, mpe oyo asalami mpo na nzela ya Afrika ya Sudi (SADC)–RDC.",
    "pt": "Quer esteja a explorar o mercado pela primeira vez ou pronto para expandir a distribuição, a ARSSA oferece-lhe um parceiro responsável durante toda a jornada — em conformidade, coordenado e concebido para o corredor África do Sul (SADC)–RDC.",
    "af": "Of jy nou die mark vir die eerste keer verken of gereed is om verspreiding op te skaal, ARSSA bied jou een verantwoordbare vennoot vir die hele reis — voldoenend, gekoördineerd en gebou vir die Suid-Afrika (SADC)–DRK-korridor.",
    "zu": "Kungakhathaliseki ukuthi uhlola imakethe ngokokuqala ngqa noma usukulungele ukukhulisa ukusabalalisa, i-ARSSA ikunikeza umlingani oyedwa oqotho kulo lonke uhambo — othobelayo, oxhumene, nowakhelwe iphaseji laseNingizimu Afrika (SADC)–DRC.",
    "xh": "Nokuba uhlola imarike okokuqala okanye ukulungele ukwandisa usasazo, i-ARSSA ikunika iqabane elinye elinoxanduva kulo lonke uhambo — elithobelayo, elilungelelanisiweyo, nelakhelwe indlela yoMzantsi Afrika (SADC)–DRC.",
    "zh": "无论您是初次涉足该市场，还是准备全面扩大分销网络，ARSSA 都将成为您全流程中唯一负责的坚实伙伴——恪守合规、严密协同，专为南非 (SADC)–刚果（金）走廊打造。",
    "ar": "سواء كنت تستكشف السوق لأول مرة أو كنت مستعداً لتوسيع نطاق التوزيع، تمنحك ARSSA شريكاً موثوقاً وخاضعاً للمساءلة لكامل مسار العمل — متوافقاً ومنسقاً ومبنياً خصيصاً لممر جنوب إفريقيا (SADC) – جمهورية الكونغو الديمقراطية.",
    "es": "Ya sea que esté explorando el mercado por primera vez o listo para escalar la distribución, ARSSA le brinda un socio responsable para todo el trayecto: conforme, coordinado y creado para el corredor Sudáfrica (SADC)–RDC.",
    "de": "Egal, ob Sie den Markt zum ersten Mal sondieren oder Ihren Vertrieb skalieren wollen: ARSSA bietet Ihnen einen verantwortlichen Partner für die gesamte Reise – regelkonform, koordiniert und maßgeschneidert für den Korridor Südafrika (SADC)–DR Kongo.",
    "hi": "चाहे आप पहली बार बाजार की खोज कर रहे हों या वितरण बढ़ाने के लिए तैयार हों, ARSSA आपको पूरी यात्रा के लिए एक जवाबदेह भागीदार देता है — अनुपालन, समन्वित और दक्षिण अफ्रीका (SADC)–DRC कॉरिडोर के लिए निर्मित।",
    "ru": "Исследуете ли вы рынок впервые или готовы масштабировать дистрибуцию, ARSSA предоставит единого ответственного партнера на всем пути — строго соблюдающего стандарты, скоординированного и созданного для коридора ЮАР (SADC) – ДР Конго.",
    "ja": "初めて市場を調査される場合でも、本格的な流通拡大を目指す場合でも、ARSSA は全工程を責任持って統括する唯一のパートナーです — 法令を順守し、統制が取れ、南アフリカ (SADC) – コンゴ民主共和国回廊のために構築されています。",
    "ko": "시장을 처음 조사하는 단계이든 유통 규모를 확장할 준비가 된 단계이든, ARSSA는 전체 여정을 책임지는 단일 파트너로서 규정 준수와 긴밀한 조율을 바탕으로 남아프리카 (SADC)–DRC 회랑 맞춤형 지원을 제공합니다.",
    "it": "Sia che tu stia esplorando il mercato per la prima volta o che sia pronto a scalare la distribuzione, ARSSA ti offre un unico partner responsabile per l'intero percorso — conforme, coordinato e strutturato per il corridoio Sudafrica (SADC)–RDC.",
    "nl": "Of u de markt nu voor het eerst verkent of klaar bent om de distributie op te schalen, ARSSA biedt u één aansprakelijke partner voor de hele reis — conform, gecoördineerd en gebouwd voor de corridor Zuid-Afrika (SADC)–DRC."
  },
