  "From market validation and regulatory licensing to customs clearance and retailer shelf presence, one partner handles the full workflow.": {
    "en": "From market validation and regulatory licensing to customs clearance and retailer shelf presence, one partner handles the full workflow.",
    "fr": "De la validation commerciale et des licences réglementaires au dédouanement et à la présence en rayon, un seul partenaire gère l'ensemble du flux.",
    "pt": "Desde a validação do mercado e licenciamento regulamentar até ao desembaraço aduaneiro e presença nas prateleiras dos retalhistas, um único parceiro gere todo o fluxo de trabalho.",
    "sw": "Kuanzia uthibitisho wa soko na leseni za udhibiti hadi kibali cha forodha na uwepo kwenye rafu za maduka, mshirika mmoja anashughulikia mlolongo mzima wa kazi.",
    "ln": "Banda na kotala zando mpe mikanda ya mibeko kino na kokata duane mpe kotia biloko na bitanda ya magazini, moninga moko azali kosala mosala nyonso mobimba.",
    "af": "Van markbevestiging en regulatoriese lisensiëring tot uitklaring by doeane en kleinhandelskapplaaslikheid, hanteer een vennoot die volledige werkvloei.",
    "zu": "Kusukela ekuqinisekisweni kwemakethe nokugunyazwa ngokusemthethweni kuya ekukhishweni kwempahla kumasiko nokubekwa ezitolo, umlingani oyedwa uphatha konke.",
    "xh": "Ukususela ekuqinisekisweni kwemarike nasekunikezelweni kwamaphepha-mvume okulawula ukuya ekucocweni kwezithethe nasekufakweni kweeshelfu zabathengisi, iqabane elinye liphatha lonke ukuhamba komsebenzi.",
    "zh": "从市场调研验证、合规资质许可，到海关报关清关和终端货架陈列，全流程由单一专业伙伴统筹承办。",
    "ar": "من التحقق من السوق والتراخيص التنظيمية إلى التخليص الجمركي وعرض المنتجات على أرفف المتاجر، يتولى شريك واحد مسار العمل بأكمله.",
    "es": "Desde la validación del mercado y licencias regulatorias hasta el despacho de aduanas y presencia en anaqueles, un solo socio gestiona todo el flujo de trabajo.",
    "de": "Von der Marktvalidierung und regulatorischen Lizenzierung bis zur Zollabfertigung und Präsenz in den Verkaufsregalen — ein Partner steuert den gesamten Ablauf.",
    "hi": "बाजार सत्यापन और नियामक लाइसेंसिंग से लेकर सीमा शुल्क निकासी और खुदरा विक्रेता शेल्फ उपस्थिति तक, एक भागीदार पूरे वर्कफ़्लो को संभालता है।",
    "ru": "От проверки рынка и получения лицензий до таможенной очистки и выкладки на полках ритейлеров — один партнер управляет всем процессом.",
    "ja": "市場検証や規制認可の取得から、通関手続き、小売店への陳列に至るまで、単一のパートナーが一連の業務をすべて対応します。",
    "ko": "시장 검증 및 규제 인허가부터 통관 및 소매점 매대 입점에 이르기까지, 단 하나의 파트너가 전체 워크플로우를 처리합니다.",
    "it": "Dalla convalida del mercato e licenze normative allo sdoganamento e presenza sugli scaffali dei rivenditori, un unico partner gestisce l'intero flusso di lavoro.",
    "nl": "Van marktvalidatie en vergunningen tot inklaring bij de douane en schapplaatsing in winkels — één partner beheert het volledige traject."
  },
