  "Our model eliminates the friction, delays, and risk of managing multiple independent vendors across two countries.": {
    "en": "Our model eliminates the friction, delays, and risk of managing multiple independent vendors across two countries.",
    "fr": "Notre modèle élimine les frictions, les retards et les risques liés à la gestion de multiples fournisseurs indépendants entre deux pays.",
    "pt": "O nosso modelo elimina o atrito, os atrasos e o risco de gerir múltiplos fornecedores independentes em dois países.",
    "sw": "Muundo wetu huondoa msuguano, ucheleweshaji na hatari ya kusimamia wauzaji wengi huru katika nchi mbili.",
    "ln": "Malamu ya mosala na biso elongolaka mitungisi, kowelela mpe likama ya kokamba basali misala ebele oyo basangani te na mikili mibale.",
    "af": "Ons model skakel die wrywing, vertragings en risiko uit om verskeie onafhanklike verskaffers oor twee lande heen te bestuur.",
    "zu": "Imodeli yethu iqeda ukungqubuzana, ukubambezeleka, kanye nengozi yokuphatha abahlinzeki abaningi abazimele emazweni amabili.",
    "xh": "Imodeli yethu iphelisa ukungquzulana, ukulibaziseka, nomngcipheko wokulawula ababoneleli abaninzi abazimeleyo kumazwe amabini.",
    "zh": "我们的一体化模式彻底消除了跨越两国协调多个独立第三方供应商所带来的推诿、延误与合规风险。",
    "ar": "يقضي نموذجنا على الاحتكاك والتأخير ومخاطر إدارة العديد من الموردين المستقلين عبر بلدين.",
    "es": "Nuestro modelo elimina la fricción, los retrasos y el riesgo de gestionar múltiples proveedores independientes en dos países.",
    "de": "Unser Modell eliminiert die Reibungsverluste, Verzögerungen und Risiken, die mit der Verwaltung mehrerer unabhängiger Dienstleister in zwei Ländern verbunden sind.",
    "hi": "हमारा मॉडल दो देशों में कई स्वतंत्र विक्रेताओं के प्रबंधन के घर्षण, देरी और जोखिम को समाप्त करता है।",
    "ru": "Наша модель устраняет трения, задержки и риски, связанные с управлением несколькими независимыми подрядчиками в двух странах.",
    "ja": "当社の統合モデルは、2国間にまたがる複数の独立ベンダーの管理に伴う摩擦、遅延、リスクを排除します。",
    "ko": "당사의 모델은 두 국가에 걸쳐 여러 독립 업체를 관리할 때 발생하는 마찰, 지연 및 위험을 제거합니다.",
    "it": "Il nostro modello elimina gli attriti, i ritardi e il rischio di gestire molteplici fornitori indipendenti in due paesi.",
    "nl": "Ons model elimineert de wrijving, vertragingen en risico's van het beheren van meerdere onafhankelijke leveranciers over twee landen heen."
  },
