  "Facilitation + Compliance + Marketing + Distribution + Trade Execution — coordinated under one accountable partner, not five disconnected vendors.": {
    "en": "Facilitation + Compliance + Marketing + Distribution + Trade Execution — coordinated under one accountable partner, not five disconnected vendors.",
    "fr": "Facilitation + Conformité + Marketing + Distribution + Exécution Commerciale — coordonnés sous un seul partenaire responsable, et non cinq fournisseurs déconnectés.",
    "pt": "Facilitação + Conformidade + Marketing + Distribuição + Execução Comercial — coordenados sob um único parceiro responsável, e não cinco fornecedores desconectados.",
    "sw": "Uwezeshaji + Uzingatiaji wa Sheria + Masoko + Usambazaji + Utekelezaji wa Biashara — umeratibiwa chini ya mshirika mmoja anayewajibika, sio wachuuzi watano wasiowasiliana.",
    "ln": "Kosalisa + Botoni mibeko + Kosakola + Kokaba biloko + Kosala mombo — nyonso esalemi na maboko ya moninga moko ya kotyela motema, kasi bato mitano oyo bayebani te te.",
    "af": "Fasilitering + Voldoening + Bemarking + Verspreiding + Handelsuitvoering — gekoördineer onder een toerekenbare vennoot, nie vyf losstaande verskaffers nie.",
    "zu": "Ukugqugquzela + Ukuhambisana Nomthetho + Ukumaketha + Ukusabalalisa + Ukwenziwa Kwezohwebo — kuxhunyaniswe ngaphansi komlingani oyedwa obophezelekile, hhayi abahlinzeki abahlanu abangaxhumene.",
    "xh": "Uququzelelo + Ukuthotyelwa Kwemithetho + Ukuthengisa + Ukusasaza + Ukwenza Urhwebo — kulungelelaniswe phantsi kweqabane elinye elinoxanduva, hayi ababoneleli abahlanu abangaqhagamshelwanga.",
    "zh": "商务落地 + 法规合规 + 市场营销 + 渠道分销 + 进出口贸易履约 —— 全流程由单一负责任伙伴通盘协调，无需对接五个各自为政的代理机构。",
    "ar": "التيسير + الامتثال + التسويق + التوزيع + التنفيذ التجاري — بتنسيق تحت شريك واحد مسؤول، وليس خمسة موردين منفصلين.",
    "es": "Facilitación + Cumplimiento + Marketing + Distribución + Ejecución Comercial: coordinados bajo un solo socio responsable, no cinco proveedores desconectados.",
    "de": "Ermöglichung + Compliance + Marketing + Vertrieb + Handelsabwicklung — koordiniert unter einem verantwortlichen Partner, nicht fünf getrennten Dienstleistern.",
    "hi": "सुविधा + अनुपालन + विपणन + वितरण + व्यापार निष्पादन — एक जवाबदेह भागीदार के तहत समन्वित, न कि पांच अलग-अलग विक्रेता।",
    "ru": "Фасилитация + Комплаенс + Маркетинг + Дистрибуция + Торговое исполнение — координация под началом одного ответственного партнера вместо пяти разобщенных подрядчиков.",
    "ja": "事業円滑化 ＋ コンプライアンス ＋ マーケティング ＋ 流通 ＋ 貿易執行 — 5社の分断された業者ではなく、1社の責任あるパートナーが統括します。",
    "ko": "비즈니스 원활화 + 규정 준수 + 마케팅 + 유통 + 무역 실행 — 단절된 5개 업체가 아닌, 단 하나의 책임 있는 파트너가 총괄 조율합니다.",
    "it": "Facilitazione + Conformità + Marketing + Distribuzione + Esecuzione Commerciale: coordinati sotto un unico partner responsabile, non cinque fornitori disconnessi.",
    "nl": "Facilitering + Naleving + Marketing + Distributie + Handelsuitvoering — gecoördineerd onder één aansprakelijke partner, niet vijf losstaande partijen."
  },
