  "We are not remote advisors — we operate on the ground in Lubumbashi, Kinshasa, Kolwezi and Johannesburg.": {
    "en": "We are not remote advisors — we operate on the ground in Lubumbashi, Kinshasa, Kolwezi and Johannesburg.",
    "fr": "Nous ne sommes pas des conseillers à distance — nous intervenons concrètement à Lubumbashi, Kinshasa, Kolwezi et Johannesburg.",
    "pt": "Não somos consultores remotos — operamos no terreno em Lubumbashi, Kinshasa, Kolwezi e Joanesburgo.",
    "sw": "Sisi sio washauri wa mbali — tunafanya kazi mashinani huko Lubumbashi, Kinshasa, Kolwezi na Johannesburg.",
    "ln": "Biso tozali te bakonzi oyo bapesi toli na mosika — tozali na mabele ya Lubumbashi, Kinshasa, Kolwezi mpe Johannesburg.",
    "af": "Ons is nie afgeleë adviseurs nie — ons opereer prakties in Lubumbashi, Kinshasa, Kolwezi en Johannesburg.",
    "zu": "Asibona abeluleki abakude — sisebenza endaweni eLubumbashi, eKinshasa, eKolwezi naseGoli.",
    "xh": "Asingobacebisi abakude — sisebenza phantsi eLubumbashi, eKinshasa, eKolwezi naseRhawutini.",
    "zh": "我们绝非纸上谈兵的远程顾问 —— 我们在卢本巴希、金沙萨、科卢韦齐和约翰内斯堡均拥有全天候实地运营团队。",
    "ar": "نحن لسنا مستشارين عن بعد — نحن نعمل على أرض الواقع في لوبومباشي وكينشاسا وكولويزي وجوهانسبرغ.",
    "es": "No somos asesores remotos: operamos sobre el terreno en Lubumbashi, Kinshasa, Kolwezi y Johannesburgo.",
    "de": "Wir sind keine Berater aus der Ferne — wir arbeiten direkt vor Ort in Lubumbashi, Kinshasa, Kolwezi und Johannesburg.",
    "hi": "हम दूरस्थ सलाहकार नहीं हैं — हम लुबुम्बाशी, किंशासा, कोल्वेज़ी और जोहान्सबर्ग में जमीन पर काम करते हैं।",
    "ru": "Мы не дистанционные консультанты — мы реально работаем на местах в Лубумбаши, Киншасе, Колвези и Йоханнесбурге.",
    "ja": "私たちは遠隔からの助言だけを行うコンサルタントではありません。ルブンバシ、キンシャサ、コルヴェジ、ヨハネスブルグの現場で直接事業を展開しています。",
    "ko": "우리는 원격 조언자만이 아닙니다. 루붐바시, 킨샤사, 콜웨지 및 요하네스버그의 현장에서 직접 발로 뛰며 운영합니다.",
    "it": "Non siamo consulenti a distanza: operiamo direttamente sul campo a Lubumbashi, Kinshasa, Kolwezi e Johannesburg.",
    "nl": "Wij zijn geen adviseurs op afstand — wij zijn daadwerkelijk aanwezig in Lubumbashi, Kinshasa, Kolwezi en Johannesburg."
  },
