  "Facilitation, compliance, marketing, distribution, and trade execution — all coordinated under a single accountable partner.": {
    "en": "Facilitation, compliance, marketing, distribution, and trade execution — all coordinated under a single accountable partner.",
    "fr": "Facilitation, conformité, marketing, distribution et exécution commerciale — le tout coordonné sous un seul partenaire responsable.",
    "pt": "Facilitação, conformidade, marketing, distribuição e execução comercial — tudo coordenado sob um único parceiro responsável.",
    "sw": "Uwezeshaji, uzingatiaji sheria, masoko, usambazaji, na utekelezaji wa biashara — yote yameratibiwa chini ya mshirika mmoja anayewajibika.",
    "ln": "Kosalisa, kotosa mibeko, kosakola, kokaba biloko mpe kosala mombo — nyonso esalemi na maboko ya moninga moko ya mokumba.",
    "af": "Fasilitering, voldoening, bemarking, verspreiding en handelsuitvoering — alles gekoördineer onder 'n enkele verantwoordbare vennoot.",
    "zu": "Ukugqugquzela, ukuhambisana nomthetho, ukumaketha, ukusabalalisa, nokwenziwa kwezohwebo — konke kuxhunyaniswe ngaphansi komlingani oyedwa obophezelekile.",
    "xh": "Uququzelelo, ukuthotyelwa kwemithetho, ukuthengisa, ukusasaza, nokwenziwa korhwebo — konke kulungelelaniswe phantsi kweqabane elinye elinoxanduva.",
    "zh": "落地促进、法规合规、市场营销、渠道分销与进出口执行 —— 全部汇聚于单一负责任的战略伙伴高效统筹。",
    "ar": "التيسير، والامتثال، والتسويق، والتوزيع، والتنفيذ التجاري — كلها منسقة تحت شريك واحد مسؤول.",
    "es": "Facilitación, cumplimiento, marketing, distribución y ejecución comercial: todo coordinado bajo un solo socio responsable.",
    "de": "Ermöglichung, Compliance, Marketing, Vertrieb und Handelsabwicklung — alles koordiniert unter einem einzigen verantwortlichen Partner.",
    "hi": "सुविधा, अनुपालन, विपणन, वितरण और व्यापार निष्पादन — सभी एक एकल जवाबदेह भागीदार के तहत समन्वित।",
    "ru": "Фасилитация, комплаенс, маркетинг, дистрибуция и исполнение торговых контрактов — все под началом единого ответственного партнера.",
    "ja": "事業円滑化、コンプライアンス、マーケティング、流通、貿易執行 — これらすべてを1社の責任あるパートナーが統括します。",
    "ko": "비즈니스 원활화, 규정 준수, 마케팅, 유통 및 무역 실행 — 단 하나의 책임 있는 파트너 아래 모두 통합 조율됩니다.",
    "it": "Facilitazione, conformità, marketing, distribuzione ed esecuzione commerciale: tutto coordinato sotto un unico partner responsabile.",
    "nl": "Facilitering, naleving, marketing, distributie en handelsuitvoering — alles gecoördineerd onder één verantwoordelijke partner."
  },
