  "Every division is built to seamlessly hand off work to the next, removing the friction and blame that happen between disparate agencies.": {
    "en": "Every division is built to seamlessly hand off work to the next, removing the friction and blame that happen between disparate agencies.",
    "fr": "Chaque division est conçue pour transmettre le travail de manière fluide à la suivante, éliminant ainsi les frictions et rejets de responsabilité entre agences disparates.",
    "pt": "Cada divisão foi criada para passar perfeitamente o trabalho para a seguinte, eliminando o atrito e as culpas que acontecem entre agências díspares.",
    "sw": "Kila kitengo kimejengwa kupeana kazi bila mshono kwa kinachofuata, kuondoa msuguano na lawama zinazotokea kati ya mashirika tofauti.",
    "ln": "Biteni nyonso ya mosala esalemi mpo na kopesana mosala na kimya, kolongola koswana mpe kofundana oyo esalemaka na bakompani mosusu.",
    "af": "Elke afdeling is gebou om werk naatloos aan die volgende oor te dra, wat die wrywing en blaam tussen verskillende agentskappe uitskakel.",
    "zu": "Uphiko ngalunye lwakhelwe ukudlulisela umsebenzi ngaphandle komthungo kulolu olulandelayo, lususe ukungqubuzana nokusolana okwenzeka phakathi kwama-ejensi ahlukene.",
    "xh": "Icandelo ngalinye lakhelwe ukunikezela umsebenzi ngaphandle komthungo kwelilandelayo, lisusa ukungquzulana nokubekana ityala okwenzeka phakathi kwee-arhente ezahlukeneyo.",
    "zh": "各大业务部门深度无缝协作衔接，杜绝各自分离的传统中介之间因交接不畅带来的推诿、摩擦与效率损耗。",
    "ar": "تم بناء كل قسم لتسليم المهام بسلاسة إلى القسم التالي، مما يزيل الاحتكاك واللوم المتبادل الذي يحدث بين الوكالات المنفصلة.",
    "es": "Cada división está diseñada para transferir el trabajo sin problemas a la siguiente, eliminando la fricción y las culpas entre agencias dispares.",
    "de": "Jede Abteilung ist darauf ausgelegt, Aufgaben nahtlos an die nächste zu übergeben — ohne Reibungsverluste oder Schuldzuweisungen zwischen verschiedenen Agenturen.",
    "hi": "प्रत्येक प्रभाग को अगले को काम सौंपने के लिए सहजता से बनाया गया है, जिससे अलग-अलग एजेंसियों के बीच होने वाले घर्षण और दोषारोपण को दूर किया जा सके।",
    "ru": "Каждое подразделение плавно передает задачи следующему, исключая трения и перекладывание вины, типичные для разных агентств.",
    "ja": "各事業部門は業務をシームレスに引き継ぐよう設計されており、分断された代理店間で発生しがちな摩擦や責任転嫁を排除します。",
    "ko": "모든 사업 부문은 업무를 다음 부문으로 매끄럽게 인계하도록 구축되어, 이질적인 대행사 간에 발생하는 마찰과 책임 전가를 없앱니다.",
    "it": "Ogni divisione è strutturata per passare il lavoro in modo fluido alla successiva, eliminando attriti e scaricabarile tra agenzie diverse.",
    "nl": "Elke divisie is ingericht om taken naadloos aan elkaar over te dragen, waardoor de wrijving en het afschuiven van schuld tussen losse bureaus verdwijnt."
  },
