  "Deep domain focus in pharmaceutical, medical, cosmetic, agri-food, agricultural inputs, and regulated corporate supply chains.": {
    "en": "Deep domain focus in pharmaceutical, medical, cosmetic, agri-food, agricultural inputs, and regulated corporate supply chains.",
    "fr": "Expertise sectorielle approfondie dans les produits pharmaceutiques, médicaux, cosmétiques, agroalimentaires, les intrants agricoles et les chaînes d'approvisionnement d'entreprise réglementées.",
    "pt": "Foco profundo nos sectores farmacêutico, médico, cosmético, agroalimentar, insumos agrícolas e cadeias de abastecimento corporativas regulamentadas.",
    "sw": "Umakini mkubwa katika dawa, matibabu, vipodozi, kilimo-chakula, pembejeo za kilimo, na minyororo ya usambazaji ya makampuni inayodhibitiwa.",
    "ln": "Boyebi ya mozindo na makambo ya bankisi, bokolongono, biloko ya bopeto, bilei, bisaleli ya bilanga mpe kokamba biloko ya kompani oyo etosaka mibeko.",
    "af": "Diepgaande fokus op farmaseutiese, mediese, kosmetiese, landbouvoedsel-, landbou-insette en gereguleerde korporatiewe voorsieningskettings.",
    "zu": "Ukugxila okujulile emithini, ezokwelapha, izimonyo, ukudla kwezolimo, izinto zezolimo, namaketanga okuhlinzeka ezinkampani alawulwayo.",
    "xh": "Ukugxila okunzulu kumayeza, ezonyango, izithambiso, ukutya kwezolimo, izixhobo zezolimo, nothungelwano lokubonelela lwenkampani olulawulwayo.",
    "zh": "深耕医药、医疗器械、美妆日化、农产品食品加工、农资农化以及严控企业级供应链。",
    "ar": "تركيز عميق في الأدوية، واللوازم الطبية، ومستحضرات التجميل، والمنتجات الغذائية الزراعية، والمدخلات الزراعية، وسلاسل التوريد المؤسسية الخاضعة للرقابة.",
    "es": "Enfoque profundo en los sectores farmacéutico, médico, cosmético, agroalimentario, insumos agrícolas y cadenas de suministro corporativas reguladas.",
    "de": "Tiefes Branchen-Know-how in Pharma, Medizin, Kosmetik, Agrar- und Lebensmitteln, landwirtschaftlichen Betriebsmitteln und regulierten Unternehmenslieferketten.",
    "hi": "फार्मास्यूटिकल, मेडिकल, कॉस्मेटिक, एग्री-फूड, एग्रीकल्चरल इनपुट्स और रेगुलेटेड कॉर्पोरेट सप्लाई चेन में गहरा डोमेन फोकस।",
    "ru": "Глубокая экспертиза в фармацевтике, медицине, косметике, агропромышленном секторе и регулируемых корпоративных цепочках поставок.",
    "ja": "製薬、医療、化粧品、農産食品、農業資材、および規制対象の企業サプライチェーンにおける高度な専門知識。",
    "ko": "제약, 의료, 화장품, 농식품, 농자재 및 규제 대상 기업 공급망에 대한 깊이 있는 산업 전문성.",
    "it": "Forte focalizzazione nei settori farmaceutico, medico, cosmetico, agroalimentare, forniture agricole e catene di fornitura aziendali regolamentate.",
    "nl": "Gespecialiseerde focus op farmacie, medische apparatuur, cosmetica, agro-food, landbouwinputs en gereguleerde zakelijke toeleveringsketens."
  },
