  "We assess your exact project requirements and structure a scope that covers your specific regulatory, commercial, and trade needs.": {
    "en": "We assess your exact project requirements and structure a scope that covers your specific regulatory, commercial, and trade needs.",
    "fr": "Nous évaluons vos exigences précises de projet et structurons un périmètre couvrant vos besoins spécifiques en matière réglementaire, commerciale et d'échanges.",
    "pt": "Avaliamos os requisitos exactos do seu projecto e estruturamos um âmbito que cobre as suas necessidades regulamentares, comerciais e de comércio específicas.",
    "sw": "Tunatathmini mahitaji yako kamili ya mradi na kuunda upeo unaojumuisha mahitaji yako mahususi ya kikanuni, kibiashara na mauzo.",
    "ln": "Tokotala malamumalamu masenga ya mosala na yo mpe tokobongisa likambo oyo ekozwa makambo na yo nyonso ya mibeko, ya mombo mpe ya biloko.",
    "af": "Ons evalueer u presiese projekvereistes en struktureer 'n bestek wat u spesifieke regulatoriese, kommersiële en handelsbehoeftes dek.",
    "zu": "Sihlola izidingo zakho eziqondile zephrojekthi futhi sakhe uhlaka oluhlanganisa izidingo zakho ezithile zokulawula, ezohwebo, nezohwebo.",
    "xh": "Sivavanya iimfuno zakho ezichanekileyo zeprojekthi kwaye simise ubungakanani obubandakanya iimfuno zakho ezithile zolawulo, zorhwebo, nezorhwebo.",
    "zh": "我们将深入评估您的具体项目诉求，为您量身构建涵盖法规合规、渠道商务及进出口贸易的一站式合作框架。",
    "ar": "نقوم بتقييم متطلبات مشروعك بدقة وبناء نطاق عمل يغطي احتياجاتك التنظيمية والتجارية وتجارة البضائع بشكل متكامل.",
    "es": "Evaluamos los requisitos exactos de su proyecto y estructuramos un alcance que cubra sus necesidades regulatorias, comerciales y de comercio exterior.",
    "de": "Wir bewerten Ihre genauen Projektanforderungen und strukturieren einen Leistungsumfang, der Ihre spezifischen regulatorischen, kommerziellen und handelsbezogenen Anforderungen abdeckt.",
    "hi": "हम आपकी सटीक परियोजना आवश्यकताओं का आकलन करते हैं और एक दायरा तैयार करते हैं जो आपकी विशिष्ट नियामक, वाणिज्यिक और व्यापारिक जरूरतों को पूरा करता है।",
    "ru": "Мы детально оценим задачи вашего проекта и сформируем план, полностью покрывающий регуляторные, коммерческие и логистические потребности.",
    "ja": "貴社のプロジェクト要件を的確に評価し、規制、商業、貿易の各ニーズを網羅した実行スコープを構築します。",
    "ko": "귀사의 정확한 프로젝트 요구사항을 분석하여 규제, 상업 및 무역 관련 요구사항을 모두 충족하는 맞춤형 실행 범위를 설계합니다.",
    "it": "Valutiamo le tue esigenze di progetto esatte e strutturiamo un ambito che copra le tue specifiche necessità normative, commerciali e di scambio.",
    "nl": "Wij inventariseren uw exacte projecteisen en stellen een plan op dat aansluit op uw specifieke regelgevende, commerciële en handelsbehoeften."
  },
