  "Cross-border expansion commonly stalls when disconnected service providers drop the ball. ARSSA integrates the full value chain to protect your capital and accelerate your timeline.": {
    "en": "Cross-border expansion commonly stalls when disconnected service providers drop the ball. ARSSA integrates the full value chain to protect your capital and accelerate your timeline.",
    "fr": "L'expansion transfrontalière s'arrête souvent lorsque des prestataires déconnectés échouent. ARSSA intègre toute la chaîne de valeur pour protéger votre capital et accélérer votre calendrier.",
    "pt": "A expansão transfronteiriça frequentemente falha quando prestadores desconectados cometem erros. A ARSSA integra toda a cadeia de valor para proteger o seu capital e acelerar o seu cronograma.",
    "sw": "Upanuzi wa mipakani mara nyingi hukwama wakati watoa huduma wasiowasiliana wanaposhindwa. ARSSA inajumuisha mnyororo mzima wa thamani ili kulinda mtaji wako na kuharakisha ratiba yako.",
    "ln": "Bokoli ya kokata bandelo ekangamaka mingi tango basali misala oyo bayebani te babebisi makambo. ARSSA esangisi banzela nyonso mpo na kobatela mbongo na yo mpe kosala noki.",
    "af": "Oorgrensuitbreiding loop dikwels vas wanneer ongekoppelde diensverskaffers foute maak. ARSSA integreer die hele waardeketting om u kapitaal te beskerm en u tydlyn te versnel.",
    "zu": "Ukwandiswa kwemingcele kuvame ukubambezeleka lapho abahlinzeki bezinsizakalo abangaxhumene behluleka. I-ARSSA ihlanganisa lonke uchungechunge lwenani ukuze ivikele imali yakho futhi isheshise isikhathi sakho.",
    "xh": "Ukwandiswa kwemida kuhlala kuthinteka xa ababoneleli beenkonzo abangaqhagamshelwanga besilela. I-ARSSA idibanisa lonke uthungelwano lwexabiso ukukhusela inkunzi yakho nokukhawulezisa ixesha lakho.",
    "zh": "跨国业务拓展往往因各个孤立的服务中介互相推诿而陷入停滞。ARSSA 整合全产业链条，切实保障您的投资资本并大幅加快落地推进节奏。",
    "ar": "غالباً ما يتوقف التوسع عبر الحدود عندما يقصر مقدمو الخدمات المنفصلون. تجمع ARSSA بين سلسلة القيمة بأكملها لحماية رأس مالك وتسريع جدولك الزمني.",
    "es": "La expansión transfronteriza a menudo se estanca cuando proveedores desconectados fallan. ARSSA integra toda la cadena de valor para proteger su capital y acelerar sus tiempos.",
    "de": "Grenzüberschreitende Expansion stockt häufig, wenn unkoordinierte Dienstleister versagen. ARSSA integriert die gesamte Wertschöpfungskette, um Ihr Kapital zu sichern und Ihren Zeitplan zu beschleunigen.",
    "hi": "सीमा पार विस्तार आमतौर पर तब रुक जाता है जब असंबद्ध सेवा प्रदाता विफल हो जाते हैं। ARSSA आपकी पूंजी की रक्षा करने और आपकी समयसीमा को तेज करने के लिए संपूर्ण मूल्य श्रृंखला को एकीकृत करता है।",
    "ru": "Трансграничная экспансия часто буксует из-за несогласованности разрозненных подрядчиков. ARSSA объединяет всю цепочку создания стоимости, защищая ваш капитал и ускоряя график запуска.",
    "ja": "国境を越えた事業拡大は、分断された外部業者の連携不足によって停滞しがちです。ARSSA はバリューチェーン全体を統合し、貴社の投資資本を保護しながらスケジュールを加速させます。",
    "ko": "국경 간 확장은 연계되지 않은 개별 서비스 제공업체들이 실책을 범할 때 정체되기 쉽습니다. ARSSA는 가치 사슬 전체를 통합하여 귀사의 자본을 보호하고 일정을 단축합니다.",
    "it": "L'espansione transfrontaliera spesso si arena quando fornitori disconnessi falliscono. ARSSA integra l'intera catena del valore per proteggere il tuo capitale e accelerare i tempi.",
    "nl": "Grensoverschrijdende expansie loopt vaak vertraging op wanneer niet-verbonden dienstverleners steken laten vallen. ARSSA integreert de volledige waardeketen om uw kapitaal te beschermen en uw planning te versnellen."
  },
  "Each division can be deployed individually or combined into an end-to-end operational roadmap.": {
    "en": "Each division can be deployed individually or combined into an end-to-end operational roadmap.",
    "fr": "Chaque division peut être déployée individuellement ou combinée dans une feuille de route opérationnelle de bout en bout.",
    "pt": "Cada divisão pode ser implementada individualmente ou combinada num roteiro operacional de ponta a ponta.",
    "sw": "Kila kitengo kinaweza kutumika kikiwa peke yake au kuunganishwa kuwa ramani kamili ya kiutendaji ya mwanzo hadi mwisho.",
    "ln": "Eteni nyonso ya mosala ekoki kosalelama yango moko to kosangisama na ebongiseli mobimba ya mosala banda ebandeli kino suka.",
    "af": "Elke afdeling kan individueel ontplooi word of gekombineer word in 'n end-tot-end operasionele padkaart.",
    "zu": "Uphiko ngalunye lungasetshenziswa ngokuzimela noma luhlanganiswe lube uhlelo lokusebenza oluphelele kusukela ekuqaleni kuya ekugcineni.",
    "xh": "Icandelo ngalinye linokusetyenziswa ngokukodwa okanye lidityaniswe kwisicwangciso sokusebenza esipheleleyo ukusuka ekuqaleni kuye ekugqibeleni.",
    "zh": "各个业务部门既可独立承接专项委托，亦可协同组合为一体化端到端全流程运营路线图。",
    "ar": "يمكن تفعيل كل قسم على حدة أو دمجه في خارطة طريق تشغيلية شاملة من البداية إلى النهاية.",
    "es": "Cada división se puede implementar individualmente o combinar en una hoja de ruta operativa integral.",
    "de": "Jeder Geschäftsbereich kann einzeln beauftragt oder zu einem durchgängigen operativen Fahrplan kombiniert werden.",
    "hi": "प्रत्येक प्रभाग को व्यक्तिगत रूप से तैनात किया जा सकता है या एंड-टू-एंड परिचालन रोडमैप में जोड़ा जा सकता है।",
    "ru": "Каждое подразделение может привлекаться отдельно либо в рамках единой комплексной дорожной карты «под ключ».",
    "ja": "各事業部門は個別に活用することも、エンドツーエンドの包括的な運用ロードマップとして統合することも可能です。",
    "ko": "각 부문은 개별적으로 활용하거나 엔드투엔드(End-to-End) 운영 로드맵으로 결합하여 유기적으로 진행할 수 있습니다.",
    "it": "Ogni divisione può essere impiegata singolarmente o combinata in una tabella di marcia operativa end-to-end.",
    "nl": "Elke divisie kan afzonderlijk worden ingezet of worden gecombineerd in een end-to-end operationeel stappenplan."
  },
