  "Each client segment faces unique regulatory, logistical, and commercial hurdles. Our five divisions coordinate to provide the exact solution needed.": {
    "en": "Each client segment faces unique regulatory, logistical, and commercial hurdles. Our five divisions coordinate to provide the exact solution needed.",
    "fr": "Chaque segment de clientèle est confronté à des obstacles réglementaires, logistiques et commerciaux uniques. Nos cinq divisions se coordonnent pour fournir la solution exacte requise.",
    "pt": "Cada segmento de clientes enfrenta obstáculos regulamentares, logísticos e comerciais únicos. As nossas cinco divisões coordenam-se para fornecer a solução exacta necessária.",
    "sw": "Kila kundi la wateja linakabiliwa na vikwazo vya kipekee vya kikanuni, vifaa na kibiashara. Vitengo vyetu vitano vinaratibiwa kutoa suluhisho sahihi linalohitajika.",
    "ln": "Kila eteni ya bakompani ekutanaka na mikakatano ya mibeko, ya kotambwisa biloko mpe ya mombo. Biteni na biso mitano esanganaka mpo na kopesa eyano ya sikisiki oyo esengeli.",
    "af": "Elke kliëntesegment staar unieke regulatoriese, logistieke en kommersiële struikelblokke in die gesig. Ons vyf afdelings koördineer om die presiese oplossing te bied wat benodig word.",
    "zu": "Ingxenye ngayinye yamakhasimende ibhekene nezithiyo ezihlukile zokulawula, ezokuthutha, nezohwebo. Izigaba zethu ezinhlanu zisebenza ndawonye ukuhlinzeka ngesixazululo esiqondile esidingekayo.",
    "xh": "Icandelo ngalinye labathengi lijongene nemiqobo ekhethekileyo yolawulo, ezolungiselelo, nezorhwebo. Amacandelo ethu amahlanu alungelelanisa ukubonelela ngesisombululo esichanekileyo esifunekayo.",
    "zh": "各类客户群体均面临其独有的政策法规、跨境物流与商业渠道壁垒。我们的五大业务部门协同配合，提供精准契合的专属解决方案。",
    "ar": "يواجه كل قطاع من العملاء عقبات تنظيمية ولوجستية وتجارية فريدة. تنسق أقسامنا الخمسة لتقديم الحل الدقيق المطلوب.",
    "es": "Cada segmento de clientes enfrenta obstáculos regulatorios, logísticos y comerciales únicos. Nuestras cinco divisiones se coordinan para brindar la solución exacta requerida.",
    "de": "Jedes Kundensegment steht vor individuellen regulatorischen, logistischen und kommerziellen Hürden. Unsere fünf Geschäftsbereiche koordinieren sich, um die exakt passende Lösung zu liefern.",
    "hi": "प्रत्येक ग्राहक वर्ग अद्वितीय नियामक, तार्किक और वाणिज्यिक बाधाओं का सामना करता है। हमारे पांच प्रभाग आवश्यक सटीक समाधान प्रदान करने के लिए समन्वय करते हैं।",
    "ru": "Каждый сегмент клиентов сталкивается со своими регуляторными, логистическими и коммерческими вызовами. Наши пять подразделений действуют согласованно, формируя точно выверенное решение.",
    "ja": "顧客セグメントごとに異なる法規制、物流、商習慣上の課題が存在します。当社の5大事業部門が緊密に連携し、まさに必要とされる的確なソリューションを提供します。",
    "ko": "고객 부문마다 고유한 규제, 물류 및 상업적 장벽에 직면합니다. 당사의 5대 사업 부문이 긴밀히 협력하여 정확히 필요한 맞춤형 솔루션을 제공합니다.",
    "it": "Ogni segmento di clienti affronta ostacoli normativi, logistici e commerciali unici. Le nostre cinque divisioni si coordinano per fornire l'esatta soluzione necessaria.",
    "nl": "Elk klantsegment heeft te maken met unieke regelgevende, logistieke en commerciële drempels. Onze vijf divisies werken samen om precies de gewenste oplossing te bieden."
  },
  "ARSSA acts as the single accountable bridge between where your business originates and where it creates commercial impact.": {
    "en": "ARSSA acts as the single accountable bridge between where your business originates and where it creates commercial impact.",
    "fr": "ARSSA agit comme le pont unique et responsable entre le lieu d'origine de votre entreprise et celui où elle crée un impact commercial.",
    "pt": "A ARSSA actua como a ponte única e responsável entre onde o seu negócio tem origem e onde cria impacto comercial.",
    "sw": "ARSSA inafanya kazi kama daraja moja linalowajibika kati ya mahali biashara yako inapoanzia na mahali inapounda matokeo ya kibiashara.",
    "ln": "ARSSA ezali gbagba moko kaka ya kotyela motema kati na esika mombo na yo ebandi mpe esika ekosala matomba ya solosolo.",
    "af": "ARSSA tree op as die enkele verantwoordbare brug tussen waar u besigheid ontstaan en waar dit kommersiële impak skep.",
    "zu": "I-ARSSA isebenza njengebhuloho elilodwa elibophezelekile phakathi kwalapho ibhizinisi lakho liqala khona nalapho lidala khona umthelela wezohwebo.",
    "xh": "I-ARSSA isebenza njengebhulorho enye enoxanduva phakathi kwalapho ishishini lakho liqala khona nalapho lidala khona impembelelo yezorhwebo.",
    "zh": "ARSSA 始终扮演单一负责任的战略桥梁，连通您企业战略发起的大本营与在刚果（金）创造商业盈利价值的核心阵地。",
    "ar": "تعمل ARSSA كجسر موثوق ومسؤول يربط بين مقر انطلاق عملك ومكان تحقيقه للأثر التجاري والربحي.",
    "es": "ARSSA actúa como el único puente responsable entre el origen de su negocio y el lugar donde genera impacto comercial.",
    "de": "ARSSA fungiert als verlässliche, zentrale Brücke zwischen dem Ursprung Ihres Unternehmens und dem Ort, an dem es kommerzielle Wirkung entfaltet.",
    "hi": "ARSSA एक एकल जवाबदेह पुल के रूप में कार्य करता है जहाँ से आपका व्यवसाय शुरू होता है और जहाँ यह वाणिज्यिक प्रभाव पैदा करता है।",
    "ru": "ARSSA выступает надежным единым мостом между базой вашего бизнеса и рынком, на котором он генерирует коммерческий результат.",
    "ja": "ARSSA は、貴社の事業発祥拠点と、実質的な商業成果を生み出す現地市場とをつなぐ、唯一の責任ある架け桥として機能します。",
    "ko": "ARSSA는 귀사의 사업이 시작되는 거점과 실질적인 상업적 성과를 창출하는 시장 사이를 잇는 단 하나의 책임 있는 가교 역할을 수행합니다.",
    "it": "ARSSA funge da unico ponte responsabile tra il luogo di origine della tua attività e quello in cui crea impatto commerciale.",
    "nl": "ARSSA fungeert als de centrale, aansprakelijke brug tussen de thuisbasis van uw bedrijf en de markt waar u commerciële impact creëert."
  },
