    "sw": "Kuongoza majalada ya kampuni, leseni na uhamaji wa wafanyakazi bila ucheleweshaji.",
    "ln": "Kokatisa mikanda ya kompani, ndingisa mpe kotambwisa basali kozanga kowelela to bowumbu.",
