  "Driving real consumer demand and dependable wholesale distribution pipelines.": {
    "en": "Driving real consumer demand and dependable wholesale distribution pipelines.",
    "fr": "Stimuler une véritable demande des consommateurs et des canaux de distribution en gros fiables.",
    "pt": "Estimular a procura real dos consumidores e canais fiáveis de distribuição grossista.",
    "sw": "Kuchochea mahitaji halisi ya watumiaji na mifereji ya usambazaji wa jumla inayotegemewa.",
    "ln": "Kotinda basombi balinga biloko na yo ya solo mpe kotonga banzela ya koteka biloko na bagrossistes ya kotyela motema.",
    "af": "Dryf werklike verbruikersvraag en betroubare groothandelverspreidingspyplyne aan.",
    "zu": "Ukugqugquzela isidingo sangempela sabathengi namaphayiphu athembekile okusabalalisa ezitolo ezinkulu.",
    "xh": "Ukuqhuba imfuno yokwenene yabathengi nemibhobho ethembekileyo yokusasaza kwiivenkile ezinkulu.",
    "zh": "全面拉动终端真实消费需求，构建稳定可持续的各级批发分销输送管道。",
    "ar": "تحفيز طلب المستهلكين الحقيقي وبناء قنوات توزيع موثوقة بالجملة.",
    "es": "Impulsar la demanda real de los consumidores y canales confiables de distribución mayorista.",
    "de": "Echte Kundennachfrage generieren und verlässliche Großhandelsvertriebskanäle aufbauen.",
    "hi": "वास्तविक उपभोक्ता मांग और भरोसेमंद थोक वितरण पाइपलाइनों को आगे बढ़ाना।",
    "ru": "Формирование реального потребительского спроса и построение надежных оптовых каналов сбыта.",
    "ja": "真の消費者需要を喚起し、信頼できる卸売流通パイプラインを確立します。",
    "ko": "실질적인 소비자 수요를 창출하고 신뢰할 수 있는 도매 유통 파이프라인을 구축합니다.",
    "it": "Guidare la reale domanda dei consumatori e costruire canali affidabili di distribuzione all'ingrosso.",
    "nl": "Het stimuleren van echte consumentenvraag en het opbouwen van betrouwbare groothandelsdistributiekanalen."
  },
