  "Eliminating customs bottlenecks, demurrage costs, and documentation errors.": {
    "en": "Eliminating customs bottlenecks, demurrage costs, and documentation errors.",
    "fr": "Éliminer les goulots d'étranglement douaniers, les frais de surestaries et les erreurs documentaires.",
    "pt": "Eliminar estrangulamentos aduaneiros, custos de sobrestadia e erros documentais.",
    "sw": "Kuondoa vikwazo vya forodha, gharama za kuchelewesha mizigo bandarini, na makosa ya hati.",
    "ln": "Kolongola mikakatano na duane, bafacture ya kowelela biloko na libongo mpe mabunga ya mikanda.",
    "af": "Uitskakeling van doeaneknelpunte, staangeldkoste en dokumentasiefoute.",
    "zu": "Ukuqeda izingqinamba zamasiko, izindleko zokubambezeleka kwempahla, namaphutha emibhalo.",
    "xh": "Ukuphelisa imiqobo yamasiko, iindleko zokulibaziseka kwempahla, neziphoso zamaxwebhu.",
    "zh": "消除海关卡点瓶颈、降低滞期堆存巨额额外成本并杜绝单证文件申报疏漏。",
    "ar": "القضاء على اختناقات الجمارك، وتكاليف رسوم التأخير (الأرضيات)، والأخطاء في المستندات.",
    "es": "Eliminar cuellos de botella aduaneros, costos de sobrestadía y errores de documentación.",
    "de": "Zollengpässe, Standgeldkosten und Dokumentationsfehler konsequent vermeiden.",
    "hi": "सीमा शुल्क बाधाओं, डिमरेज लागत और दस्तावेज़ीकरण त्रुटियों को समाप्त करना।",
    "ru": "Ликвидация таможенных заторов, штрафов за простой и ошибок в документации.",
    "ja": "通関時のボトルネック、超過保管料（デマレージ）、書類の不備・エラーを徹底排除。",
    "ko": "통관 병목 현상, 체선료/지체료 발생 및 서류 작성 오류를 원천 차단합니다.",
    "it": "Eliminare i colli di bottiglia doganali, i costi di controstallia e gli errori documentali.",
    "nl": "Het elimineren van douane-knelpunten, overliggelden en documentatiefouten."
  },
