  "ARSSA provides focused commercial and operational support for mining-related activity across the South Africa (SADC)–DRC corridor.": {
    "en": "ARSSA provides focused commercial and operational support for mining-related activity across the South Africa (SADC)–DRC corridor.",
    "fr": "ARSSA fournit un soutien commercial et opérationnel ciblé pour les activités liées au secteur minier le long du corridor Afrique du Sud (SADC)–RDC.",
    "pt": "A ARSSA fornece apoio comercial e operacional focado para actividades relacionadas com a mineração ao longo do corredor África do Sul (SADC)–RDC.",
    "sw": "ARSSA inatoa usaidizi thabiti wa kibiashara na kiutendaji kwa shughuli zinazohusiana na madini katika korido ya Afrika Kusini (SADC)–DRC.",
    "ln": "ARSSA epesaka lisalisi ya mombo mpe ya mosala mpo na misala ya mabanga ya ntalo na nzela ya Afríka ya Súdi (SADC)–RDC.",
    "af": "ARSSA bied gefokusde kommersiële en operasionele ondersteuning vir mynbouverwante aktiwiteite oor die Suid-Afrika (SADC)–DRK-korridor heen.",
    "zu": "I-ARSSA ihlinzeka ngokusekelwa kwezohwebo nokusebenza okugxilile emisebenzini ehlobene nezimayini kulo lonke iphasishi laseNingizimu Afrika (SADC)–DRC.",
    "xh": "I-ARSSA ibonelela ngenkxaso ejolisiweyo yezorhwebo neyokusebenza kwimisebenzi enxulumene nemigodi kummandla woMzantsi Afrika (SADC)–DRC.",
    "zh": "ARSSA 为南非（SADC）与刚果（金）跨境走廊沿线的矿业关联供应链、设备物资采购与合规协同提供高度专业化的商业及运营支持。",
    "ar": "توفر ARSSA دعماً تجارياً وتشغيلياً متخصصاً للأنشطة المرتبطة بقطاع التعدين عبر ممر جنوب أفريقيا (SADC)–جمهورية الكونغو الديمقراطية.",
    "es": "ARSSA brinda soporte comercial y operativo enfocado para actividades relacionadas con la minería a lo largo del corredor Sudáfrica (SADC)–RDC.",
    "de": "ARSSA bietet zielgerichtete kommerzielle und operative Unterstützung für bergbaubezogene Aktivitäten entlang des Korridors Südafrika (SADC)–DR Kongo.",
    "hi": "ARSSA दक्षिण अफ्रीका (SADC)-DRC गलियारे में खनन से संबंधित गतिविधियों के लिए केंद्रित वाणिज्यिक और परिचालन सहायता प्रदान करता है।",
    "ru": "ARSSA оказывает целевую коммерческую и операционную поддержку предприятиям горнодобывающего сектора в коридоре Южная Африка (SADC) — ДРК.",
    "ja": "ARSSA は、南アフリカ（SADC）〜コンゴ民主共和国回廊における鉱業関連のサプライチェーン、機材調達、パートナーシップに対し、専門的な商業・運用支援を提供します。",
    "ko": "ARSSA는 남아공(SADC)-콩고민주공화국 회랑 전반에서 광업 관련 활동을 위한 집중적인 상업 및 운영 지원을 제공합니다.",
    "it": "ARSSA fornisce supporto commerciale e operativo mirato per le attività legate al settore minerario lungo il corridoio Sudafrica (SADC)–RDC.",
    "nl": "ARSSA biedt gerichte commerciële en operationele ondersteuning voor mijnbouwgerelateerde activiteiten in de corridor Zuid-Afrika (SADC)–DRC."
  },
  "We keep this support practical: helping identify the right partners, coordinate supply and introductions, and move opportunities toward clear next steps.": {
    "en": "We keep this support practical: helping identify the right partners, coordinate supply and introductions, and move opportunities toward clear next steps.",
    "fr": "Nous maintenons ce soutien pragmatique : aider à identifier les bons partenaires, coordonner l'approvisionnement et les présentations, et faire avancer les opportunités vers des étapes suivantes claires.",
    "pt": "Mantemos este apoio prático: ajudando a identificar os parceiros certos, coordenar fornecimentos e apresentações, e avançar as oportunidades para próximos passos claros.",
    "sw": "Tunaweka usaidizi huu kuwa wa vitendo: kusaidia kutambua washirika sahihi, kuratibu ugavi na utambulisho, na kusogeza fursa kuelekea hatua zilizo wazi zinazofuata.",
    "ln": "Tosalaka mosala oyo na pambala ya solo: kosalisa kotala baninga ya malamu, kokamba kopesa biloko mpe koyebana na bato, mpe kotambwisa makambo na mikano ya polele oyo elandi.",
    "af": "Ons hou hierdie ondersteuning prakties: help om die regte vennote te identifiseer, voorrade en bekendstellings te koördineer, en geleenthede na duidelike volgende stappe te beweeg.",
    "zu": "Sigcina lokhu kusekelwa kusebenza: ukusiza ukuhlonza ozakwethu abafanele, ukuxhumanisa ukuhlinzekwa kanye nokwethulwa, nokuhambisa amathuba ezinyathelweni ezicacile ezilandelayo.",
    "xh": "Sigcina le nkxaso isebenza ngendlela efanelekileyo: ukunceda ukuchonga amaqabane afanelekileyo, ukulungelelanisa unikezelo kunye nokwaziswa, nokuhambisa amathuba kumanyathelo acacileyo alandelayo.",
    "zh": "我们始终坚持求真务实的原则：协助您精准锁定经过背景审查的合格伙伴、协调物资设备供应链与商业引荐，稳健推动矿业合作机遇迈向明确的实操阶段。",
    "ar": "نحرص على أن يكون هذا الدعم عملياً: المساعدة في تحديد الشركاء المناسبين، وتنسيق التوريد والتعارف التجاري، وتحويل الفرص إلى خطوات ملموسة وواضحة.",
    "es": "Mantenemos este apoyo de manera práctica: ayudando a identificar a los socios adecuados, coordinar el suministro y presentaciones, y avanzar las oportunidades hacia pasos claros.",
    "de": "Wir halten diese Unterstützung praxisnah: Wir helfen dabei, die richtigen Partner zu identifizieren, Lieferketten und Geschäftskontakte zu koordinieren und Chancen in greifbare nächste Schritte umzusetzen.",
    "hi": "हम इस समर्थन को व्यावहारिक रखते हैं: सही भागीदारों की पहचान करने, आपूर्ति और परिचय का समन्वय करने और अवसरों को स्पष्ट अगले कदमों की ओर ले जाने में मदद करना।",
    "ru": "Мы действуем исключительно практично: помогаем подобрать надежных партнеров, организуем поставки оборудования и прямые контакты, переводя возможности в четкие проектные шаги.",
    "ja": "実践的な支援に徹します。最適なビジネスパートナーの特定、資材供給と商談機会の調整、そして具体的な次のアクションへの進展を強力にサポートします。",
    "ko": "우리는 실질적인 지원을 원칙으로 합니다. 적합한 파트너를 발굴하고, 공급망과 비즈니스 매칭을 조율하며, 기회를 구체적인 다음 단계로 확실히 진전시킵니다.",
    "it": "Manteniamo questo supporto estremamente pratico: aiutiamo a individuare i partner giusti, coordinare le forniture e le introduzioni commerciali, guidando le opportunità verso passi successivi chiari.",
    "nl": "Wij houden onze ondersteuning praktisch: we helpen de juiste partners te identificeren, leveringen en introducties te coördineren en kansen om te zetten in duidelijke vervolgstappen."
  },
