  "Thank you for contacting ARSSA. We've received your enquiry and our team will review it and respond with next steps shortly.": {
    "en": "Thank you for contacting ARSSA. We've received your enquiry and our team will review it and respond with next steps shortly.",
    "fr": "Merci d'avoir contacté ARSSA. Nous avons bien reçu votre demande et notre équipe l'examinera pour vous répondre dans les plus brefs délais avec les prochaines étapes.",
    "pt": "Obrigado por contactar a ARSSA. Recebemos a sua consulta e a nossa equipa irá analisá-la e responder em breve com os próximos passos.",
    "sw": "Asante kwa kuwasiliana na ARSSA. Tumepokea ombi lako na timu yetu italikagua na kujibu kwa hatua zinazofuata hivi karibuni.",
    "ln": "Matondo mingi mpo na kobenga ARSSA. Toyambi motuna na yo mpe ekipi na biso ekotola yango mpe ekozongisela yo eyano na noki mpo na makambo oyo ekolanda.",
    "af": "Dankie dat u ARSSA gekontak het. Ons het u navraag ontvang en ons span sal dit hersien en binnekort met volgende stappe reageer.",
    "zu": "Siyabonga ngokuxhumana ne-ARSSA. Siwutholile umbuzo wakho futhi ithimba lethu lizowubuyekeza futhi liphendule ngezinyathelo ezilandelayo maduze.",
    "xh": "Enkosi ngokuqhagamshelana ne-ARSSA. Sisiwufumene umbuzo wakho kwaye iqela lethu liza kuwuhlolisisa kwaye liphendule ngamanyathelo alandelayo kungekudala.",
    "zh": "衷心感谢您垂询 ARSSA。我们已收到您的业务咨询，我们的管理团队将在短时间内完成评估并向您回复后续推进方案与详细建议。",
    "ar": "شكراً لتواصلك مع ARSSA. لقد تلقينا استفسارك وسيقوم فريقنا بمراجعته والرد عليك بالخطوات التالية قريباً.",
    "es": "Gracias por contactar a ARSSA. Hemos recibido su consulta y nuestro equipo la revisará para responderle pronto con los siguientes pasos.",
    "de": "Vielen Dank für Ihre Kontaktaufnahme mit ARSSA. Wir haben Ihre Anfrage erhalten. Unser Team wird diese prüfen und sich in Kürze mit den nächsten Schritten bei Ihnen melden.",
    "hi": "ARSSA से संपर्क करने के लिए धन्यवाद। हमें आपकी पूछताछ प्राप्त हो गई है और हमारी टीम इसकी समीक्षा करेगी और शीघ्र ही अगले कदमों के साथ जवाब देगी।",
    "ru": "Благодарим за обращение в ARSSA. Ваш запрос получен, наша команда оперативно изучит его и свяжется с вами для обсуждения дальнейших шагов.",
    "ja": "ARSSA へのお問い合わせありがとうございます。ご相談内容を受領いたしました。担当チームが内容を精査の上、今後の具体的な進め方について折り返しご連絡いたします。",
    "ko": "ARSSA에 문의해 주셔서 감사합니다. 접수된 문의 사항을 경영진이 면밀히 검토한 후 향후 진행 절차에 대해 신속하게 안내해 드리겠습니다.",
    "it": "Grazie per aver contattato ARSSA. Abbiamo ricevuto la tua richiesta; il nostro team la esaminerà e ti risponderà a breve con i passaggi successivi.",
    "nl": "Hartelijk dank voor uw contact met ARSSA. We hebben uw aanvraag ontvangen en ons team zal deze beoordelen en binnenkort reageren met de vervolgstappen."
  },
