    "ja": "貴社が必要とされているサポート内容、および ARSSA がどのように目標達成に貢献できるかお聞かせください…",
    "ko": "필요하신 사항과 ARSSA가 귀사의 목표를 어떻게 지원할 수 있는지 알려주세요…",
