  "ARSSA acts as an integrated bridge connecting businesses, suppliers, investors and commercial opportunities with the DRC, while facilitating trade and market access across regional and international markets.": {
    "en": "ARSSA acts as an integrated bridge connecting businesses, suppliers, investors and commercial opportunities with the DRC, while facilitating trade and market access across regional and international markets.",
    "fr": "ARSSA agit comme un pont intégré reliant les entreprises, les fournisseurs, les investisseurs et les opportunités commerciales à la RDC, tout en facilitant le commerce et l'accès au marché sur les marchés régionaux et internationaux.",
    "pt": "A ARSSA actua como uma ponte integrada que liga empresas, fornecedores, investidores e oportunidades comerciais à RDC, facilitando o comércio e o acesso ao mercado em mercados regionais e internacionais.",
    "sw": "ARSSA inafanya kazi kama daraja jumuishi linalounganisha biashara, wasambazaji, wawekezaji na fursa za kibiashara na DRC, huku ikiwezesha biashara na ufikiaji wa soko katika masoko ya kikanda na kimataifa.",
    "ln": "ARSSA ezali gbagba oyo esangisi nyonso kokangisa bakompani, bapesani biloko, batiyi mbongo mpe mabaku ya mombo na RDC, kosalisa mombo mpe kozwa nzela na bazando ya zoni mpe ya mokili mobimba.",
    "af": "ARSSA tree op as 'n geïntegreerde brug wat besighede, verskaffers, beleggers en kommersiële geleenthede met die DRK verbind, terwyl handel en marktoegang oor streeks- en internasionale markte heen gefasiliteer word.",
    "zu": "I-ARSSA isebenza njengebhuloho elihlanganisiwe elixhumanisa amabhizinisi, abahlinzeki, abatshalizimali namathuba ezohwebo ne-DRC, ngenkathi igqugquzela uhwebo nokungena emakethe ezimakethe zesifunda nezamazwe ngamazwe.",
    "xh": "I-ARSSA isebenza njengebhulorho edibeneyo edibanisa amashishini, ababoneleli, abatyali-zimali namathuba ezorhwebo ne-DRC, ngelixa iququzelela urhwebo nokufikelela emarikeni kwiimarike zengingqi nezamazwe ngamazwe.",
    "zh": "ARSSA 作为一体化商业桥梁，紧密连接各大企业、供应商、投资者与刚果（金）的商业合作机遇，并在区域及国际市场上全力促进经贸往来与市场准入。",
    "ar": "تعمل ARSSA كجسر متكامل يربط بين الشركات والموردين والمستثمرين والفرص التجارية وجمهورية الكونغو الديمقراطية، مع تيسير التجارة والوصول إلى الأسواق الإقليمية والدولية.",
    "es": "ARSSA actúa como un puente integrado que conecta empresas, proveedores, inversores y oportunidades comerciales con la RDC, facilitando el comercio y el acceso al mercado en mercados regionales e internacionales.",
    "de": "ARSSA fungiert als integrierte Brücke, die Unternehmen, Lieferanten, Investoren und Geschäftsmöglichkeiten mit der DR Kongo verbindet und gleichzeitig den Handel und den Marktzugang auf regionalen und internationalen Märkten erleichtert.",
    "hi": "ARSSA व्यवसायों, आपूर्तिकर्ताओं, निवेशकों और वाणिज्यिक अवसरों को डीआरसी से जोड़ने वाले एक एकीकृत पुल के रूप में कार्य करता है, जबकि क्षेत्रीय और अंतर्राष्ट्रीय बाजारों में व्यापार और बाजार पहुंच की सुविधा प्रदान करता है।",
    "ru": "ARSSA выступает интегрированным мостом, соединяющим предприятия, поставщиков, инвесторов и коммерческие возможности с ДРК, содействуя торговле и выходу на региональные и международные рынки.",
    "ja": "ARSSA は、企業、サプライヤー、投資家、商業機会をコンゴ民主共和国と結ぶ統合ブリッジとして機能し、地域市場および国際市場全体での貿易と市場アクセスを促進します。",
    "ko": "ARSSA는 기업, 공급업체, 투자자 및 상업적 기회를 콩고민주공화국과 연결하는 통합 가교 역할을 하며, 지역 및 국제 시장 전반에서 무역과 시장 접근성을 촉진합니다.",
    "it": "ARSSA funge da ponte integrato che collega aziende, fornitori, investitori e opportunità commerciali con la RDC, facilitando il commercio e l'accesso ai mercati regionali e internazionali.",
    "nl": "ARSSA fungeert als een geïntegreerde brug die bedrijven, leveranciers, investeerders en commerciële kansen verbindt met de DRC, terwijl handel en markttoegang op regionale en internationale markten worden gefaciliteerd."
  },
  "Businesses, investors, manufacturers, suppliers and strategic partners seeking access to the DRC market.": {
    "en": "Businesses, investors, manufacturers, suppliers and strategic partners seeking access to the DRC market.",
    "fr": "Entreprises, investisseurs, fabricants, fournisseurs et partenaires stratégiques cherchant à accéder au marché de la RDC.",
    "pt": "Empresas, investidores, fabricantes, fornecedores e parceiros estratégicos que procuram acesso ao mercado da RDC.",
    "sw": "Biashara, wawekezaji, wazalishaji, wasambazaji na washirika wa kimkakati wanaotafuta kuingia katika soko la DRC.",
    "ln": "Bakompani, batiyi mbongo, basali biloko, bapesani biloko mpe baninga ya mayele oyo balingi kokota na zando ya RDC.",
    "af": "Besighede, beleggers, vervaardigers, verskaffers en strategiese vennote wat toegang tot die DRK-mark soek.",
    "zu": "Amabhizinisi, abatshalizimali, abakhiqizi, abahlinzeki nabalingani bamasu abafuna ukungena emakethe ye-DRC.",
    "xh": "Amashishini, abatyali-zimali, abavelisi, ababoneleli namaqabane obuchule afuna ukufikelela kwimarike yase-DRC.",
    "zh": "寻求进入刚果（金）市场的各界企业、投资人、生产制造商、原料设备供应商与战略合作伙伴。",
    "ar": "الشركات والمستثمرون والمصنعون والموردون والشركاء الاستراتيجيون الذين يسعون للوصول إلى سوق جمهورية الكونغو الديمقراطية.",
    "es": "Empresas, inversores, fabricantes, proveedores y socios estratégicos que buscan acceder al mercado de la RDC.",
    "de": "Unternehmen, Investoren, Hersteller, Lieferanten und strategische Partner, die Zugang zum Markt der DR Kongo suchen.",
    "hi": "डीआरसी बाजार तक पहुंच चाहने वाले व्यवसाय, निवेशक, निर्माता, आपूर्तिकर्ता और रणनीतिक साझेदार।",
    "ru": "Предприятия, инвесторы, производители, поставщики и стратегические партнеры, стремящиеся выйти на рынок ДРК.",
    "ja": "コンゴ民主共和国市場への参入を目指す企業、投資家、製造業者、サプライヤー、戦略的パートナー。",
    "ko": "콩고민주공화국 시장 진출을 희망하는 기업, 투자자, 제조업체, 공급업체 및 전략적 파트너.",
    "it": "Aziende, investitori, produttori, fornitori e partner strategici che desiderano accedere al mercato della RDC.",
    "nl": "Bedrijven, investeerders, fabrikanten, leveranciers en strategische partners die toegang zoeken tot de DRC-markt."
  },
