  "Practical support for mining-related sourcing, workforce placement, partnerships, supplies and commercial coordination across the DRC–Southern Africa trade corridor.": {
    "en": "Practical support for mining-related sourcing, workforce placement, partnerships, supplies and commercial coordination across the DRC–Southern Africa trade corridor.",
    "fr": "Soutien pratique pour l'approvisionnement minier, le placement de main-d'œuvre, les partenariats, les fournitures et la coordination commerciale le long du corridor commercial RDC–Afrique australe.",
    "pt": "Apoio prático para aprovisionamento mineiro, colocação de mão-de-obra, parcerias, fornecimentos e coordenação comercial no corredor comercial RDC–África Austral.",
    "sw": "Usaidizi wa vitendo kwa ununuzi wa vifaa vya migodi, upangaji wa nguvu kazi, ushirikiano, ugavi na uratibu wa kibiashara katika ukanda wa biashara wa DRC–Kusini mwa Afrika.",
    "ln": "Lisalisi ya solo mpo na kozwa biloko ya mabele ya talo, kopesa basali misala, boyokani, biloko mpe kokamba mombongo na nzela ya mombo RDC–Afríka ya Súdi na zoni.",
    "af": "Praktiese ondersteuning vir mynbouverwante verkryging, werksmagplasing, vennootskappe, voorrade en kommersiële koördinering oor die DRK–Suider-Afrika-handelskorridor.",
    "zu": "Ukwesekwa okusebenzayo kokuthola izinsiza zezimayini, ukubekwa kwabasebenzi, ubambiswano, impahla nokuxhumana kwezohwebo ephasishini lokuhweba le-DRC–Ningizimu Afrika.",
    "xh": "Inkxaso esebenzayo yokufumana izixhobo zokumba, ukubekwa kwabasebenzi, ubudlelwane, unikezelo lweempahla kunye nolungelelaniso lorhwebo kumda we-DRC–Mazantsi e-Afrika.",
    "zh": "为刚果（金）–南部非洲贸易走廊提供矿产设备物资采购、专业人才派遣配置、合资合作与全流程商业统筹落地支持。",
    "ar": "دعم عملي لعمليات التوريد الخاصة بقطاع التعدين، وتوظيف الكوادر الفنية، وبناء الشراكات، وتوريد المعدات والتنسيق التجاري عبر ممر التجارة بين الكونغو الديمقراطية والجنوب الأفريقي.",
    "es": "Apoyo práctico para abastecimiento minero, colocación de personal técnico, alianzas estratégicas, suministros y coordinación comercial en el corredor comercial RDC–África Austral.",
    "de": "Praktische Unterstützung für bergbaubezogene Beschaffung, Fachkräftevermittlung, Partnerschaften, Industriegüter und kommerzielle Koordination im Handelskorridor DR Kongo–Südliches Afrika.",
    "hi": "डीआरसी-दक्षिणी अफ्रीका व्यापार गलियारे में खनन संबंधी सोर्सिंग, कार्यबल प्लेसमेंट, साझेदारी, आपूर्ति और वाणिज्यिक समन्वय के लिए व्यावहारिक सहायता।",
    "ru": "Практическое содействие в закупках для горнодобывающей отрасли, подборе кадров, партнерствах, поставках и коммерческой координации по торговому коридору ДРК – Южная Африка.",
    "ja": "コンゴ民主共和国–南部アフリカ貿易回廊における鉱業資機材調達、専門人材派遣・配置、アライアンス、サプライチェーンおよび商業調整の実践的支援。",
    "ko": "콩고민주공화국–남부 아프리카 무역 회랑 전반에 걸친 광업 소싱, 전문 인력 파견 및 배치, 전략적 제휴, 자재 공급 및 상업적 조율을 위한 실질적 현장 지원.",
    "it": "Supporto pratico per l'approvvigionamento minerario, il collocamento della manodopera, partnership, forniture e coordinamento commerciale lungo il corridoio commerciale RDC–Africa australe.",
    "nl": "Praktische ondersteuning voor mijnbouwgerelateerde inkoop, personeelsplaatsing, partnerschappen, leveringen en commerciële coördinatie over de handelscorridor DRC–Zuidelijk Afrika."
  },
