  "Helping bridge workforce and skills gaps in the mining sector through targeted recruitment and placement of qualified technical, operational and professional personnel for mining companies, contractors and service providers.": {
    "en": "Helping bridge workforce and skills gaps in the mining sector through targeted recruitment and placement of qualified technical, operational and professional personnel for mining companies, contractors and service providers.",
    "fr": "Combler les déficits de main-d'œuvre et de compétences dans le secteur minier grâce au recrutement ciblé et au placement de personnel technique, opérationnel et professionnel qualifié pour les compagnies minières, les sous-traitants et les prestataires.",
    "pt": "Ajudando a colmatar as lacunas de mão-de-obra e competências no sector mineiro através do recrutamento orientado e colocação de pessoal técnico, operacional e profissional qualificado para empresas mineiras, empreiteiros e prestadores de serviços.",
    "sw": "Kusaidia kuziba mapengo ya nguvu kazi na ujuzi katika sekta ya madini kupitia uajiri maalum na upangaji wa wafanyakazi wenye sifa za kiufundi, kiutendaji na kitaaluma kwa kampuni za uchimbaji madini, makandarasi na watoa huduma.",
    "ln": "Kosalisa kolongola bopamboli ya basali mpe mayele na sektele ya mabele ya talo na nzela ya kozwa mpe kopesa basali ya tekiniki, ya mosala mpe ya mayele mpo na bakompani ya mabele, bakontraktere mpe bapesani misala.",
    "af": "Help om werksmag- en vaardigheidsgapings in die mynbousektor te oorbrug deur geteikende werwing en plasing van gekwalifiseerde tegniese, operasionele en professionele personeel vir mynboumaatskappye, kontrakteurs en diensverskaffers.",
    "zu": "Ukusiza ukuvala igebe labasebenzi namakhono emkhakheni wezimayini ngokuqasha okuhlosiwe nokubeka abasebenzi bezobuchwepheshe, abasebenzayo nabaqeqeshiwe ezinkampanini zezimayini, osonkontileka nabahlinzeki bezinsizakalo.",
    "xh": "Ukunceda ukuvala izikhewu zabasebenzi nezakhono kwicandelo lezemigodi ngokuqesha okujolisiweyo kunye nokubekwa kwabasebenzi abaqeqeshiweyo bezobugcisa, ukusebenza nobungcali kwiinkampani zezemigodi, iikontraki kunye nababoneleli beenkonzo.",
    "zh": "通过精准招聘与选拔派遣高素质的技术、实操及管理专业人才，协助矿业企业、工程总包商及专业服务商弥合现场用工与高技能人才缺口。",
    "ar": "المساعدة في سد فجوات القوى العاملة والمهارات في قطاع التعدين من خلال التوظيف المستهدف وتعيين الكوادر الفنية والتشغيلية والمهنية المؤهلة لشركات التعدين والمقاولين ومقدمي الخدمات.",
    "es": "Ayudar a cerrar las brechas de personal y habilidades en el sector minero a través de la contratación dirigida y la colocación de personal técnico, operativo y profesional calificado para empresas mineras, contratistas y proveedores de servicios.",
    "de": "Schließen von Personal- und Qualifikationslücken im Bergbausektor durch gezielte Rekrutierung und Vermittlung von qualifiziertem technischem, operativem und professionellem Personal für Bergbauunternehmen, Auftragnehmer und Dienstleister.",
    "hi": "खनन कंपनियों, ठेकेदारों और सेवा प्रदाताओं के लिए योग्य तकनीकी, परिचालन और पेशेवर कर्मियों की लक्षित भर्ती और प्लेसमेंट के माध्यम से खनन क्षेत्र में कार्यबल और कौशल अंतराल को पाटने में मदद करना।",
    "ru": "Содействие в устранении кадрового и квалификационного дефицита в горнодобывающем секторе посредством целевого подбора и расстановки квалифицированного инженерного, рабочего и управленческого персонала для добывающих компаний, подрядчиков и сервисных предприятий.",
    "ja": "鉱山会社、コントラクター、サービスプロバイダー向けに、資格を有する技術・オペレーション・専門管理職のターゲット採用と派遣を通じて、鉱業分野の人材・スキルギャップを解消します。",
    "ko": "광업 기업, 계약업체 및 서비스 제공업체를 위해 검증된 기술, 운영 및 전문 인력의 맞춤형 채용 및 파견을 통해 광업 부문의 인력 및 기술 격차를 해소합니다.",
    "it": "Aiutare a colmare le carenze di manodopera e competenze nel settore minerario attraverso il reclutamento mirato e l'inserimento di personale tecnico, operativo e professionale qualificato per società minerarie, appaltatori e fornitori di servizi.",
    "nl": "Het dichten van personeels- en vaardigheidstekorten in de mijnbouwsector door gerichte werving en plaatsing van gekwalificeerd technisch, operationeel en professioneel personeel voor mijnbouwbedrijven, aannemers en dienstverleners."
  },
